def resolve(schema, comps, depth=0):
    if depth>10: return schema
    if not isinstance(schema, dict): return schema
    if '$ref' in schema:
        ref=schema['$ref'].split('/')[-1]
        return resolve(comps[ref], comps, depth+1)
    out={}
    for k,v in schema.items():
        if k=='properties':
            out[k]={pk:resolve(pv,comps,depth+1) for pk,pv in v.items()}
        elif k=='items':
            out[k]=resolve(v,comps,depth+1)
        elif k=='allOf':
            merged={'type':'object','properties':{},'required':[]}
            for part in v:
                r=resolve(part,comps,depth+1)
                if isinstance(r,dict):
                    merged['properties'].update(r.get('properties',{}))
                    merged['required']=list(set(merged.get('required',[])+r.get('required',[])))
                    for kk,vv in r.items():
                        if kk not in ('properties','required'):
                            merged[kk]=vv
            out=merged
        else:
            out[k]=v
    return out

