        _, err := s.DB.SQL.Exec(`INSERT INTO sessions (token, user_id, active_role, expires_at) VALUES ($1,$2,$3,$4)`, token, userID, activeRole, exp)
        return token, err
}

func (s *Store) GetSession(token string) (userID, activeRole string, err error) {
        var exp time.Time
        err = s.DB.SQL.QueryRow(`SELECT user_id, active_role, expires_at FROM sessions WHERE token=$1`, token).Scan(&userID, &activeRole, &exp)
        if err != nil {
                return "", "", err
        }
        if time.Now().UTC().After(exp) {
                _, _ = s.DB.SQL.Exec(`DELETE FROM sessions WHERE token=$1`, token)
                return "", "", sql.ErrNoRows
        }
        return userID, activeRole, nil
}

