func (s *Store) ConfigureCapacity(resourceID string, units, cooled int) error {
        // try location first
        res, err := s.DB.SQL.Exec(`UPDATE locations SET capacity_units=$2, cooled_capacity_units=$3, updated_at=now() WHERE id=$1`, resourceID, units, cooled)
        if err != nil {
                return err
        }
        n, _ := res.RowsAffected()
        if n > 0 {
                return nil
        }
        res, err = s.DB.SQL.Exec(`UPDATE connections SET capacity_units=$2, cooled_capacity_units=$3, updated_at=now() WHERE id=$1`, resourceID, units, cooled)
        if err != nil {
                return err
        }
        n, _ = res.RowsAffected()
        if n == 0 {
                return sql.ErrNoRows
        }
        return nil
}

