func (s *Store) ConfigureLabAcceptance(labID, sampleTypeID string, accepts bool) (string, error) {
        var existing string
        err := s.DB.SQL.QueryRow(`SELECT id FROM lab_acceptances WHERE laboratory_id=$1 AND sample_type_id=$2`, labID, sampleTypeID).Scan(&existing)
        if err == sql.ErrNoRows {
                id := util.NewID()
                _, err = s.DB.SQL.Exec(`INSERT INTO lab_acceptances (id, laboratory_id, sample_type_id, accepts) VALUES ($1,$2,$3,$4)`, id, labID, sampleTypeID, accepts)
                if err != nil {
                        return "", err
                }
                // also update location accepted list
                _ = s.syncLabAccepted(labID)
                return id, nil
        }
        if err != nil {
                return "", err
        }
        _, err = s.DB.SQL.Exec(`UPDATE lab_acceptances SET accepts=$3 WHERE id=$1`, existing, accepts)
        // fix: wrong placeholders
        _, err = s.DB.SQL.Exec(`UPDATE lab_acceptances SET accepts=$2 WHERE id=$1`, existing, accepts)
        if err != nil {
                return "", err
        }
        _ = s.syncLabAccepted(labID)
        return existing, nil
}

func (s *Store) syncLabAccepted(labID string) error {
        rows, err := s.DB.SQL.Query(`SELECT sample_type_id FROM lab_acceptances WHERE laboratory_id=$1 AND accepts=true`, labID)
        if err != nil {
                return err
        }
        defer rows.Close()
        var ids []string
        for rows.Next() {
                var id string
                _ = rows.Scan(&id)
                ids = append(ids, id)
        }
        if ids == nil {
                ids = []string{}
        }
        _, err = s.DB.SQL.Exec(`UPDATE locations SET accepted_sample_type_ids=$2 WHERE id=$1`, labID, models.MustJSON(ids))
        return err
}

func (s *Store) LabAccepts(labID, sampleTypeID string) bool {
        var accepts bool
        err := s.DB.SQL.QueryRow(`SELECT accepts FROM lab_acceptances WHERE laboratory_id=$1 AND sample_type_id=$2`, labID, sampleTypeID).Scan(&accepts)
        if err != nil {
                return false
        }
        return accepts
}

