func (s *Store) SearchAudit(query, actorID, entityType, entityID, action, role string, success *bool, fromTime, toTime *time.Time, limit, offset int, order string) ([]models.AuditEntry, int, error) {
        ctx := context.Background()
        filter := bson.M{}
        if actorID != "" {
                filter["actorId"] = actorID
        }
        if entityType != "" {
                filter["entityType"] = entityType
        }
        if entityID != "" {
                filter["entityId"] = entityID
        }
        if action != "" {
                filter["action"] = action
        }
        if role != "" {
                filter["role"] = role
        }
        if success != nil {
                filter["success"] = *success
        }
        if fromTime != nil || toTime != nil {
                tr := bson.M{}
                if fromTime != nil {
                        tr["$gte"] = *fromTime
                }
                if toTime != nil {
                        tr["$lte"] = *toTime
                }
                filter["occurredAt"] = tr
        }
        if query != "" {
                filter["$or"] = []bson.M{
                        {"action": bson.M{"$regex": query, "$options": "i"}},
                        {"entityType": bson.M{"$regex": query, "$options": "i"}},
                        {"entityId": bson.M{"$regex": query, "$options": "i"}},
                        {"actorId": bson.M{"$regex": query, "$options": "i"}},
                }
        }
        coll := s.DB.MongoDB.Collection("audit_logs")
        total, err := coll.CountDocuments(ctx, filter)
        if err != nil {
                return nil, 0, err
        }
        sortDir := -1
        if order == "oldest_first" {
                sortDir = 1
        }
        opts := options.Find().SetSort(bson.D{{Key: "occurredAt", Value: sortDir}}).SetSkip(int64(offset)).SetLimit(int64(limit))
        cur, err := coll.Find(ctx, filter, opts)
        if err != nil {
                return nil, 0, err
        }
        defer cur.Close(ctx)
        var out []models.AuditEntry
        for cur.Next(ctx) {
                var doc bson.M
                if err := cur.Decode(&doc); err != nil {
                        continue
                }
                e := models.AuditEntry{
                        AuditID:    strVal(doc["auditId"]),
                        ActorID:    strVal(doc["actorId"]),
                        Role:       strVal(doc["role"]),
                        ActorRole:  strVal(doc["actorRole"]),
                        Action:     strVal(doc["action"]),
                        EntityType: strVal(doc["entityType"]),
                        EntityID:   strVal(doc["entityId"]),
                        Success:    boolVal(doc["success"]),
                        Details:    map[string]interface{}{},
                }
                if t, ok := doc["occurredAt"].(time.Time); ok {
                        e.OccurredAt = util.FormatTime(t)
                } else {
                        e.OccurredAt = util.FormatTime(time.Now().UTC())
                }
                if d, ok := doc["details"].(bson.M); ok {
                        for k, v := range d {
                                e.Details[k] = v
                        }
                }
                // dual keys for contract
                out = append(out, e)
        }
        if out == nil {
                out = []models.AuditEntry{}
        }
        return out, int(total), nil
}

func strVal(v interface{}) string {
        if v == nil {
                return ""
        }
        switch t := v.(type) {
        case string:
                return t
        default:
                return fmt.Sprintf("%v", t)
        }
}

func boolVal(v interface{}) bool {
        if b, ok := v.(bool); ok {
                return b
        }
        return false
}

