                {Name: "Frost", QualifiedCollectorRequired: true, RequiredQualification: "Frost", ContainerType: "cooled", TemperatureMinC: 2, TemperatureMaxC: 8, RequiresCooledRoute: true, BatchingAllowed: true},
                {Name: "Pulse", QualifiedCollectorRequired: true, RequiredQualification: "Pulse", ContainerType: "standard", TemperatureMinC: 2, TemperatureMaxC: 25, RequiresCooledRoute: false, BatchingAllowed: false},
        }
        // Set Amber/Indigo incompatibility after create
        var amberID, indigoID string
        for i := range defaults {
                existing, err := s.GetSampleTypeByName(defaults[i].Name)
                if err == nil && existing != nil {
                        if defaults[i].Name == "Amber" {
                                amberID = existing.ID
                        }
                        if defaults[i].Name == "Indigo" {
                                indigoID = existing.ID
                        }
                        continue
                }
                defaults[i].IncompatibleSampleTypes = []string{}
                if err := s.CreateSampleType(&defaults[i]); err != nil {
                        if !strings.Contains(err.Error(), "duplicate") && !strings.Contains(err.Error(), "unique") {
                                return err
                        }
                }
                if defaults[i].Name == "Amber" {
                        amberID = defaults[i].ID
                }
                if defaults[i].Name == "Indigo" {
                        indigoID = defaults[i].ID
                }
        }
        if amberID != "" && indigoID != "" {
                amber, _ := s.GetSampleType(amberID)
                indigo, _ := s.GetSampleType(indigoID)
                if amber != nil {
                        amber.IncompatibleSampleTypes = []string{indigoID}
                        _ = s.UpdateSampleType(amber)
                }
                if indigo != nil {
                        indigo.IncompatibleSampleTypes = []string{amberID}
                        _ = s.UpdateSampleType(indigo)
                }
        }
        return nil
}

func (s *Store) EnsureAdmin(username, password string) error {
        n, err := s.CountUsers()
        if err != nil {
                return err
        }
        if n > 0 {
                return nil
        }
        if username == "" {
                username = "admin"
        }
        if password == "" {
                password = "admin"
        }
        u := &models.User{
                Username:       username,
                Roles:          []string{models.RoleAdministrator},
                Qualifications: []string{},
                Certifications: []models.Certification{},
                Active:         true,
                FullName:       util.Ptr("System Administrator"),
        }
        return s.CreateUser(u, password)
}"}

