        }
        var originNodeID *string
        if v, ok := req["originNodeId"].(string); ok && v != "" {
                originNodeID = &v
        }
        requestedAt, err := util.ParseTime(str(req["requestedAt"]))
        if err != nil {
                return nil, fmt.Errorf("invalid_time")
        }
        deadline, err := util.ParseTime(str(req["deliveryDeadline"]))
        if err != nil {
                return nil, fmt.Errorf("invalid_deadline")
