func (s *Store) GetSample(id string) (*models.Sample, error) {
        row := s.DB.SQL.QueryRow(`SELECT id, request_id, requester_id, origin_lat, origin_lon, origin_type, origin_node_id, requested_at, delivery_deadline, earliest_collection_at, latest_collection_at, sample_type_id, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, state, sealed, sealed_at, already_sealed, current_holder_id, active_journey_id, target_laboratory_id, received_laboratory_id, serviceability, serviceability_reason, location_lat, location_lon, location_recorded_at, exception_code, exception_message, pending_handoff_id, requires_cooled, batching_allowed FROM samples WHERE id=$1`, id)
        return s.scanSample(row)
}

func (s *Store) scanSample(row *sql.Row) (*models.Sample, error) {
        var sm models.Sample
        var originNode, holder, journey, target, received, svcReason, excCode, excMsg, pendingHO sql.NullString
        var earliest, latest, sealedAt, locAt sql.NullTime
        var lat, lon sql.NullFloat64
        var incompat []byte
        err := row.Scan(&sm.ID, &sm.RequestID, &sm.RequesterID, &sm.OriginLat, &sm.OriginLon, &sm.OriginType, &originNode,
                &sm.RequestedAt, &sm.DeliveryDeadline, &earliest, &latest, &sm.SampleTypeID, &sm.ContainerType,
                &sm.TemperatureMinC, &sm.TemperatureMaxC, &incompat, &sm.State, &sm.Sealed, &sealedAt, &sm.AlreadySealed,
                &holder, &journey, &target, &received, &sm.Serviceability, &svcReason, &lat, &lon, &locAt,
                &excCode, &excMsg, &pendingHO, &sm.RequiresCooled, &sm.BatchingAllowed)
        if err != nil {
                return nil, err
        }
        sm.IncompatibleSampleTypes = models.ParseStringSlice(incompat)
        if originNode.Valid {
                sm.OriginNodeID = &originNode.String
        }
        if earliest.Valid {
                t := earliest.Time
                sm.EarliestCollectionAt = &t
        }
        if latest.Valid {
                t := latest.Time
                sm.LatestCollectionAt = &t
        }
        if sealedAt.Valid {
                t := sealedAt.Time
                sm.SealedAt = &t
        }
        if holder.Valid {
                sm.CurrentHolderID = &holder.String
        }
        if journey.Valid {
                sm.ActiveJourneyID = &journey.String
        }
        if target.Valid {
                sm.TargetLaboratoryID = &target.String
        }
        if received.Valid {
                sm.ReceivedLaboratoryID = &received.String
        }
        if svcReason.Valid {
                sm.ServiceabilityReason = svcReason.String
        }
        if lat.Valid {
                sm.LocationLat = &lat.Float64
        }
        if lon.Valid {
                sm.LocationLon = &lon.Float64
        }
        if locAt.Valid {
                t := locAt.Time
                sm.LocationRecordedAt = &t
        }
        if excCode.Valid {
                sm.ExceptionCode = &excCode.String
        }
        if excMsg.Valid {
                sm.ExceptionMessage = &excMsg.String
        }
        if pendingHO.Valid {
                sm.PendingHandoffID = &pendingHO.String
        }
        return &sm, nil
}

func (s *Store) UpdateSample(sm *models.Sample) error {
        _, err := s.DB.SQL.Exec(`UPDATE samples SET state=$2, sealed=$3, sealed_at=$4, current_holder_id=$5, active_journey_id=$6, target_laboratory_id=$7, received_laboratory_id=$8, serviceability=$9, serviceability_reason=$10, location_lat=$11, location_lon=$12, location_recorded_at=$13, exception_code=$14, exception_message=$15, pending_handoff_id=$16, updated_at=now() WHERE id=$1`,
                sm.ID, sm.State, sm.Sealed, sm.SealedAt, sm.CurrentHolderID, sm.ActiveJourneyID, sm.TargetLaboratoryID, sm.ReceivedLaboratoryID,
                sm.Serviceability, nullIfEmpty(sm.ServiceabilityReason), sm.LocationLat, sm.LocationLon, sm.LocationRecordedAt,
                sm.ExceptionCode, sm.ExceptionMessage, sm.PendingHandoffID)
        return err
}

func (s *Store) ListSamples() ([]*models.Sample, error) {
        rows, err := s.DB.SQL.Query(`SELECT id FROM samples ORDER BY created_at DESC`)
        if err != nil {
                return nil, err
        }
        defer rows.Close()
        var out []*models.Sample
        for rows.Next() {
                var id string
                if err := rows.Scan(&id); err != nil {
                        return nil, err
                }
                sm, err := s.GetSample(id)
                if err != nil {
                        continue
                }
                out = append(out, sm)
        }
        return out, nil
}

func (s *Store) ListSamplesByRequester(requesterID string) ([]*models.Sample, error) {
        rows, err := s.DB.SQL.Query(`SELECT id FROM samples WHERE requester_id=$1 ORDER BY created_at DESC`, requesterID)
        if err != nil {
                return nil, err
        }
        defer rows.Close()
        var out []*models.Sample
        for rows.Next() {
                var id string
                _ = rows.Scan(&id)
                sm, err := s.GetSample(id)
                if err == nil {
                        out = append(out, sm)
                }
        }
        return out, nil
}

func nullIfEmpty(s string) interface{} {
        if s == "" {
