func (s *Store) findEligibleWorker(role, sampleTypeID string, locationID *string, exclude map[string]bool) *models.User {
        users, err := s.ListUsers()
        if err != nil {
                return nil
        }
        type cand struct {
                u     *models.User
                score int
        }
        var cands []cand
        now := util.Now()
        for _, u := range users {
                if !u.Active || !u.Available {
                        continue
                }
                if exclude != nil && exclude[u.ID] {
                        continue
                }
                hasRole := false
                for _, r := range u.Roles {
                        if r == role {
                                hasRole = true
                        }
                }
                if !hasRole {
                        continue
                }
                if u.DeclinePenaltyUntil != nil && u.DeclinePenaltyUntil.After(now) {
                        // lower priority but still eligible
                }
                if role == "collection_professional" && sampleTypeID != "" {
                        st, err := s.GetSampleType(sampleTypeID)
                        if err != nil {
                                continue
                        }
                        if st.QualifiedCollectorRequired {
                                ok := false
                                for _, q := range u.Qualifications {
                                        if q == st.RequiredQualification || q == st.Name {
                                                ok = true
                                        }
                                }
                                for _, c := range u.Certifications {
                                        if c.Active && (c.Code == st.RequiredQualification || c.Code == st.Name) {
                                                ok = true
                                        }
                                }
                                if !ok {
                                        continue
                                }
                        }
                }
                if (role == "node_handler" || role == "laboratory_team") && locationID != nil {
                        if u.AssignedLocationID == nil || *u.AssignedLocationID != *locationID {
                                continue
                        }
                }
                score := u.RecentAssignmentCount
                if u.DeclinePenaltyUntil != nil && u.DeclinePenaltyUntil.After(now) {
                        score += 100
                }
                cands = append(cands, cand{u, score})
        }
        if len(cands) == 0 {
                return nil
        }
        sort.Slice(cands, func(i, j int) bool {
                return cands[i].score < cands[j].score
        })
        return cands[0].u
}

func (s *Store) reserveCapacity(resourceType, resourceID, sampleID, journeyID string, units int, cooled bool) error {
        id := util.NewID()
        _, err := s.DB.SQL.Exec(`INSERT INTO capacity_reservations (id, resource_type, resource_id, sample_id, journey_id, units, cooled, active) VALUES ($1,$2,$3,$4,$5,$6,$7,true)`,
                id, resourceType, resourceID, sampleID, journeyID, units, cooled)
        if err != nil {
                return err
        }
        if resourceType == "location" {
                if cooled {
                        _, err = s.DB.SQL.Exec(`UPDATE locations SET reserved_units = reserved_units + $2, cooled_reserved_units = cooled_reserved_units + $2 WHERE id=$1`, resourceID, units)
                } else {
                        _, err = s.DB.SQL.Exec(`UPDATE locations SET reserved_units = reserved_units + $2 WHERE id=$1`, resourceID, units)
                }
        } else if resourceType == "connection" {
                if cooled {
                        _, err = s.DB.SQL.Exec(`UPDATE connections SET reserved_units = reserved_units + $2, cooled_reserved_units = cooled_reserved_units + $2 WHERE id=$1`, resourceID, units)
                } else {
                        _, err = s.DB.SQL.Exec(`UPDATE connections SET reserved_units = reserved_units + $2 WHERE id=$1`, resourceID, units)
                }
        }
        return err
}

func (s *Store) releaseCapacityForJourney(journeyID string) error {
        rows, err := s.DB.SQL.Query(`SELECT id, resource_type, resource_id, units, cooled FROM capacity_reservations WHERE journey_id=$1 AND active=true`, journeyID)
        if err != nil {
                return err
        }
        defer rows.Close()
        type res struct {
                id, rt, rid string
                units       int
                cooled      bool
        }
        var list []res
        for rows.Next() {
                var r res
                _ = rows.Scan(&r.id, &r.rt, &r.rid, &r.units, &r.cooled)
                list = append(list, r)
        }
        for _, r := range list {
                _, _ = s.DB.SQL.Exec(`UPDATE capacity_reservations SET active=false WHERE id=$1`, r.id)
                if r.rt == "location" {
                        if r.cooled {
                                _, _ = s.DB.SQL.Exec(`UPDATE locations SET reserved_units = GREATEST(0, reserved_units - $2), cooled_reserved_units = GREATEST(0, cooled_reserved_units - $2) WHERE id=$1`, r.rid, r.units)
                        } else {
                                _, _ = s.DB.SQL.Exec(`UPDATE locations SET reserved_units = GREATEST(0, reserved_units - $2) WHERE id=$1`, r.rid, r.units)
                        }
                } else {
                        if r.cooled {
                                _, _ = s.DB.SQL.Exec(`UPDATE connections SET reserved_units = GREATEST(0, reserved_units - $2), cooled_reserved_units = GREATEST(0, cooled_reserved_units - $2) WHERE id=$1`, r.rid, r.units)
                        } else {
                                _, _ = s.DB.SQL.Exec(`UPDATE connections SET reserved_units = GREATEST(0, reserved_units - $2) WHERE id=$1`, r.rid, r.units)
                        }
                }
        }
        return nil
}

func (s *Store) JourneyToAPI(j *models.Journey, assignments []*models.Assignment) map[string]interface{} {
        legs := []map[string]interface{}{}
        for _, a := range assignments {
                if a.Kind != "transport" && a.Kind != "collection" {
                        // include transport and collection as legs? contract JourneyLeg is for transport mostly
                }
                leg := map[string]interface{}{
                        "assignmentId": a.ID,
                        "sequence":     a.Sequence,
                        "status":       a.Status,
                }
                if a.FromLocationID != nil {
                        leg["fromLocationId"] = *a.FromLocationID
                }
                if a.ToLocationID != nil {
                        leg["toLocationId"] = *a.ToLocationID
                }
                if a.WorkerID != nil {
                        leg["workerId"] = *a.WorkerID
                }
                if a.SampleID != nil {
                        leg["sampleId"] = *a.SampleID
                }
                if a.Kind == "transport" || a.Kind == "collection" {
                        legs = append(legs, leg)
                }
        }
        // sort legs by sequence
        sort.Slice(legs, func(i, j int) bool {
                return legs[i]["sequence"].(int) < legs[j]["sequence"].(int)
        })

        out := map[string]interface{}{
                "journeyId":   j.ID,
                "planVersion": j.PlanVersion,
                "routeMode":   j.RouteMode,
                "status":      j.Status,
                "sampleIds":   j.SampleIDs,
                "orderedStops": j.OrderedStops,
                "legs":        legs,
        }
        if j.ParentJourneyID != nil {
                out["parentJourneyId"] = *j.ParentJourneyID
        }
        if j.EstimatedDeliveryAt != nil {
                out["estimatedDeliveryAt"] = util.FormatTime(*j.EstimatedDeliveryAt)
        }
        out["totalCostUnits"] = j.TotalCostUnits
        out["capacityUsed"] = j.CapacityUsed
        out["capacityAvailable"] = j.CapacityAvailable
        out["assignedWorkerIds"] = j.AssignedWorkerIDs
        out["collectionAssignmentIds"] = j.CollectionAssignmentIDs
        if len(j.CollectionAssignmentIDs) > 0 {
                out["collectionAssignmentId"] = j.CollectionAssignmentIDs[0]
        }
        out["nodeAssignmentIds"] = j.NodeAssignmentIDs
        out["laboratoryAssignmentIds"] = j.LaboratoryAssignmentIDs
        if j.FirstTransportAssignmentID != nil {
                out["firstTransportAssignmentId"] = *j.FirstTransportAssignmentID
        }
        if j.MiddleTransportAssignmentID != nil {
                out["middleTransportAssignmentId"] = *j.MiddleTransportAssignmentID
        }
        if j.FinalTransportAssignmentID != nil {
                out["finalTransportAssignmentId"] = *j.FinalTransportAssignmentID
        }
        return out
}

func (s *Store) RecomputeServiceabilitySnapshot() error {
        locs, err := s.ListLocations()
        if err != nil {
                return err
        }
        var regions []map[string]interface{}
        activeCP := 0
        for _, l := range locs {
                if l.HasActiveFunction("collection_point") {
                        activeCP++
                        regions = append(regions, map[string]interface{}{
                                "locationId": l.ID,
                                "name":       l.Name,
                                "latitude":   l.Coordinate.Latitude,
                                "longitude":  l.Coordinate.Longitude,
                                "coverageKm": l.CoverageKm,
                        })
                }
        }
        if regions == nil {
                regions = []map[string]interface{}{}
        }
        rev, ver, _, _, _ := s.GetNetworkMeta()
        newVer := ver + 1
        _, _ = s.DB.SQL.Exec(`UPDATE network_meta SET serviceability_version=$1, serviceability_status='complete', serviceability_computed_at=now() WHERE id=1`, newVer)

        ctx := contextBackground()
        // keep previous while inserting new - we insert complete version
        _, err = s.DB.MongoDB.Collection("serviceability_snapshots").InsertOne(ctx, map[string]interface{}{
                "version":                    newVer,
                "status":                     "complete",
                "computedAt":                 time.Now().UTC(),
                "networkRevision":            rev,
                "regions":                    regions,
                "activeCollectionPointCount": activeCP,
        })
        return err
}

func contextBackground() context.Context {
        return context.Background()
}

// helpers
func toFloat(v interface{}) (float64, bool) {
        switch t := v.(type) {
        case float64:
                return t, true
        case float32:
                return float64(t), true
        case int:
                return float64(t), true
        case int64:
                return float64(t), true
        case json.Number:
                f, err := t.Float64()
                return f, err == nil
        default:
                return 0, false
        }
}

func str(v interface{}) string {
        if v == nil {
                return ""
        }
        if s, ok := v.(string); ok {
                return s
        }
        return fmt.Sprintf("%v", v)
}

func toStringSlice(v interface{}) []string {
        if v == nil {
                return []string{}
        }
        arr, ok := v.([]interface{})
        if !ok {
                if s, ok := v.([]string); ok {
                        return s
                }
                return []string{}
        }
        var out []string
        for _, x := range arr {
                out = append(out, str(x))
        }
        return out
}

// Fix duplicate shortestPath - remove the stub
// Actually the first shortestPath with wrong signature will cause compile error.
// I'll fix samples.go by removing the stub version via a separate fix.
"}

{"path":"/workspace/backend/internal/api/helpers.go","command":"create","file_text":"package api

import (
        "encoding/json"
        "io"
        "net/http"
        "strings"

        "labpd/internal/models"
        "labpd/internal/service"
        "labpd/internal/util"
)

type contextKey string

const ctxUserKey contextKey = "user"
const ctxRoleKey contextKey = "role"
const ctxTokenKey contextKey = "token"

type Handler struct {
        Store *service.Store
}

func (h *Handler) decodeJSON(r *http.Request, dst interface{}) error {
        defer r.Body.Close()
        dec := json.NewDecoder(r.Body)
        dec.DisallowUnknownFields()
        if err := dec.Decode(dst); err != nil {
                if err == io.EOF {
                        return err
                }
                return err
        }
        return nil
}

func (h *Handler) decodeJSONMap(r *http.Request) (map[string]interface{}, error) {
        defer r.Body.Close()
        var m map[string]interface{}
        dec := json.NewDecoder(r.Body)
        dec.UseNumber()
        if err := dec.Decode(&m); err != nil {
                return nil, err
        }
        if m == nil {
                m = map[string]interface{}{}
        }
        return m, nil
}

func (h *Handler) currentUser(r *http.Request) *models.User {
        v := r.Context().Value(ctxUserKey)
        if v == nil {
                return nil
        }
        return v.(*models.User)
}

func (h *Handler) activeRole(r *http.Request) string {
        v := r.Context().Value(ctxRoleKey)
        if v == nil {
                return ""
        }
        return v.(string)
}

func (h *Handler) token(r *http.Request) string {
        v := r.Context().Value(ctxTokenKey)
        if v == nil {
                return ""
        }
        return v.(string)
}

func (h *Handler) requireAuth(w http.ResponseWriter, r *http.Request) (*models.User, string, bool) {
        u := h.currentUser(r)
        if u == nil {
                util.WriteError(w, http.StatusUnauthorized, "unauthorized", "authentication required")
                return nil, "", false
        }
        role := h.activeRole(r)
        return u, role, true
}

func (h *Handler) requireRole(w http.ResponseWriter, r *http.Request, allowed ...string) (*models.User, string, bool) {
        u, role, ok := h.requireAuth(w, r)
        if !ok {
                return nil, "", false
        }
        if role == "" {
                util.WriteError(w, http.StatusConflict, "role_not_selected", "active role must be selected")
                return nil, "", false
        }
        // administrator can do dispatcher things
        for _, a := range allowed {
                if role == a {
                        return u, role, true
                }
                if a == models.RoleDispatcher && role == models.RoleAdministrator {
                        return u, role, true
                }
                if a == models.RoleAdministrator && role == models.RoleAdministrator {
                        return u, role, true
                }
        }
        // check if user holds the role at all for forbidden vs role_not_selected
        holds := false
        for _, ur := range u.Roles {
                for _, a := range allowed {
                        if ur == a {
                                holds = true
                        }
                }
        }
        if !holds && role != models.RoleAdministrator {
                util.WriteError(w, http.StatusForbidden, "forbidden", "insufficient permissions")
                return nil, "", false
        }
        util.WriteError(w, http.StatusForbidden, "forbidden", "active role not permitted for this action")
        return nil, "", false
}

func (h *Handler) audit(u *models.User, role, action, entityType, entityID string, success bool, details map[string]interface{}) {
        actorID := "system"
        if u != nil {
                actorID = u.ID
        }
        _ = h.Store.AddAudit(actorID, role, action, entityType, entityID, success, details)
}

func (h *Handler) withIdempotency(w http.ResponseWriter, r *http.Request, key, op string, fn func() (int, interface{})) {
        if key == "" {
                util.WriteError(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
                return
        }
        if st, body, ok := h.Store.GetIdempotency(key); ok {
                w.Header().Set("Content-Type", "application/json")
                w.WriteHeader(st)
                _, _ = w.Write(body)
                return
        }
        status, data := fn()
        // only save success responses
        if status >= 200 && status < 300 {
                resp := map[string]interface{}{"data": data}
                _ = h.Store.SaveIdempotency(key, "", op, status, resp)
                util.WriteData(w, status, data)
                return
        }
        // error already written by fn? we need convention: fn returns error info
        if errMap, ok := data.(map[string]interface{}); ok {
                if code, ok := errMap["code"].(string); ok {
                        msg, _ := errMap["error"].(string)
                        util.WriteError(w, status, code, msg)
                        return
                }
        }
        util.WriteData(w, status, data)
}

func errBody(code, msg string) map[string]interface{} {
        return map[string]interface{}{"error": msg, "code": code}
}

func hasRole(u *models.User, role string) bool {
        for _, r := range u.Roles {
                if r == role {
                        return true
                }
        }
        return false
}

func bearerToken(r *http.Request) string {
        h := r.Header.Get("Authorization")
        if h == "" {
                return ""
        }
        parts := strings.SplitN(h, " ", 2)
        if len(parts) != 2 || !strings.EqualFold(parts[0], "Bearer") {
                return ""
        }
        return strings.TrimSpace(parts[1])
}

func locationStale(sm *models.Sample) bool {
        if sm.LocationRecordedAt == nil {
                return true
        }
        return util.Now().Sub(*sm.LocationRecordedAt).Minutes() > float64(models.LocationStaleMinutes)
}

func sampleStateAPI(sm *models.Sample, timeline []models.TimelineEntry, activeAssignmentIDs []string) map[string]interface{} {
        out := map[string]interface{}{
                "sampleId":                sm.ID,
                "requestId":               sm.RequestID,
                "requesterId":             sm.RequesterID,
                "origin":                  map[string]interface{}{"latitude": sm.OriginLat, "longitude": sm.OriginLon},
                "originType":              sm.OriginType,
                "requestedAt":             util.FormatTime(sm.RequestedAt),
                "deliveryDeadline":        util.FormatTime(sm.DeliveryDeadline),
                "sampleTypeId":            sm.SampleTypeID,
                "containerType":           sm.ContainerType,
                "temperatureMinC":         sm.TemperatureMinC,
                "temperatureMaxC":         sm.TemperatureMaxC,
                "incompatibleSampleTypes": sm.IncompatibleSampleTypes,
                "serviceability":          sm.Serviceability,
                "activeAssignmentIds":     activeAssignmentIDs,
                "state":                   sm.State,
                "timeline":                timeline,
                "locationStale":           locationStale(sm),
        }
        if sm.ActiveJourneyID != nil {
                out["activeJourneyId"] = *sm.ActiveJourneyID
        }
        if sm.TargetLaboratoryID != nil {
                out["targetLaboratoryId"] = *sm.TargetLaboratoryID
        }
        if sm.LocationLat != nil && sm.LocationLon != nil {
                out["latestLocation"] = map[string]interface{}{"latitude": *sm.LocationLat, "longitude": *sm.LocationLon}
        }
        if sm.LocationRecordedAt != nil {
                out["locationRecordedAt"] = util.FormatTime(*sm.LocationRecordedAt)
        }
        return out
}

func sampleLifecycleAPI(sm *models.Sample, timeline []models.TimelineEntry, completedLegIDs []string) map[string]interface{} {
        out := map[string]interface{}{
                "sampleId":                 sm.ID,
                "status":                   sm.State,
                "sealed":                   sm.Sealed,
                "completedLegIds":          completedLegIDs,
                "activeReplacementPlanIds": []string{},
                "timeline":                 timeline,
                "locationStale":            locationStale(sm),
        }
        if sm.ActiveJourneyID != nil {
                out["activeJourneyId"] = *sm.ActiveJourneyID
        }
        if sm.CurrentHolderID != nil {
                out["currentHolderId"] = *sm.CurrentHolderID
        }
        if sm.ReceivedLaboratoryID != nil {
                out["receivedLaboratoryId"] = *sm.ReceivedLaboratoryID
        }
        if sm.ExceptionCode != nil {
                out["exception"] = map[string]interface{}{
                        "code":    *sm.ExceptionCode,
                        "message": util.StrOr(sm.ExceptionMessage, ""),
                }
        }
        if sm.PendingHandoffID != nil {
                out["pendingHandoffId"] = *sm.PendingHandoffID
        }
        if sm.LocationLat != nil && sm.LocationLon != nil {
                out["latestLocation"] = map[string]interface{}{"latitude": *sm.LocationLat, "longitude": *sm.LocationLon}
        }
        if sm.LocationRecordedAt != nil {
                out["locationRecordedAt"] = util.FormatTime(*sm.LocationRecordedAt)
        }
        return out
}"}

{"path":"/workspace/backend/internal/api/handlers_auth.go","command":"create","file_text":"package api

import (
        "database/sql"
        "net/http"

        "labpd/internal/models"
        "labpd/internal/util"
)

func (h *Handler) AuthenticateUser(w http.ResponseWriter, r *http.Request) {
        var body struct {
                Username string `json:"username"`
                Password string `json:"password"`
        }
        if err := h.decodeJSON(r, &body); err != nil {
                util.WriteError(w, 400, "invalid_json", "invalid request body")
                return
        }
        u, err := h.Store.GetUserByUsername(body.Username)
        if err != nil || u == nil || !u.Active || !h.Store.CheckPassword(u.PasswordHash, body.Password) {
                h.audit(nil, "", "authenticate_user", "user", body.Username, false, nil)
                util.WriteError(w, 401, "invalid_credentials", "invalid username or password")
                return
        }
        activeRole := ""
        if len(u.Roles) == 1 {
                activeRole = u.Roles[0]
        }
        token, err := h.Store.CreateSession(u.ID, activeRole)
        if err != nil {
                util.WriteError(w, 500, "internal_error", "failed to create session")
                return
        }
        h.audit(u, activeRole, "authenticate_user", "user", u.ID, true, nil)
        util.WriteData(w, 200, map[string]interface{}{
                "sessionToken": token,
                "userId":       u.ID,
                "roles":        u.Roles,
                "activeRole":   activeRole,
        })
}

func (h *Handler) SelectActiveRole(w http.ResponseWriter, r *http.Request) {
        u, _, ok := h.requireAuth(w, r)
        if !ok {
                return
        }
        var body struct {
                Role string `json:"role"`
        }
        if err := h.decodeJSON(r, &body); err != nil {
                util.WriteError(w, 400, "invalid_json", "invalid request body")
                return
        }
        if body.Role == "" {
                util.WriteError(w, 400, "invalid_role", "role is required")
                return
        }
        if !hasRole(u, body.Role) {
                util.WriteError(w, 409, "role_not_held", "user does not hold this role")
                return
        }
        if err := h.Store.SetActiveRole(h.token(r), body.Role); err != nil {
                util.WriteError(w, 500, "internal_error", "failed to set role")
                return
        }
        h.audit(u, body.Role, "select_active_role", "user", u.ID, true, map[string]interface{}{"role": body.Role})
        util.WriteData(w, 200, map[string]interface{}{
                "activeRole": body.Role,
                "roles":      u.Roles,
        })
}

func (h *Handler) CreateUser(w http.ResponseWriter, r *http.Request) {
        u, role, ok := h.requireRole(w, r, models.RoleAdministrator)
        if !ok {
                return
        }
        m, err := h.decodeJSONMap(r)
        if err != nil {
                util.WriteError(w, 400, "invalid_json", "invalid request body")
                return
        }
        username, _ := m["username"].(string)
        password, _ := m["initialPassword"].(string)
        if username == "" || password == "" {
                util.WriteError(w, 400, "invalid_user", "username and password required")
                return
        }
        if existing, _ := h.Store.GetUserByUsername(username); existing != nil {
                util.WriteError(w, 409, "username_exists", "username already exists")
                return
        }
        roles := toStringSlice(m["roles"])
        if len(roles) == 0 {
                util.WriteError(w, 400, "invalid_user", "roles required")
                return
        }
        active := true
        if v, ok := m["active"].(bool); ok {
                active = v
        }
        quals := toStringSlice(m["qualifications"])
        certs := parseCerts(m["certifications"])
        nu := &models.User{
                Username: username, Roles: roles, Qualifications: quals, Certifications: certs, Active: active,
        }
        if v, ok := m["email"].(string); ok {
                nu.Email = &v
        }
        if v, ok := m["fullName"].(string); ok {
                nu.FullName = &v
        }
        if v, ok := m["phone"].(string); ok {
                nu.Phone = &v
        }
        if v, ok := m["assignedLocationId"].(string); ok && v != "" {
                nu.AssignedLocationID = &v
        }
        if err := h.Store.CreateUser(nu, password); err != nil {
                util.WriteError(w, 500, "internal_error", err.Error())
                return
        }
        h.audit(u, role, "create_user", "user", nu.ID, true, map[string]interface{}{"username": username})
        util.WriteData(w, 201, userAPI(nu))
}

func (h *Handler) UpdateUserAccess(w http.ResponseWriter, r *http.Request) {
        u, role, ok := h.requireRole(w, r, models.RoleAdministrator)
        if !ok {
                return
        }
        m, err := h.decodeJSONMap(r)
        if err != nil {
                util.WriteError(w, 400, "invalid_json", "invalid request body")
                return
        }
        userID, _ := m["userId"].(string)
        target, err := h.Store.GetUser(userID)
        if err != nil {
                util.WriteError(w, 404, "not_found", "user not found")
                return
        }
        roles := toStringSlice(m["roles"])
        active, _ := m["active"].(bool)
        quals := toStringSlice(m["qualifications"])
        if m["qualifications"] == nil {
                quals = target.Qualifications
        }
        certs := parseCerts(m["certifications"])
        if m["certifications"] == nil {
                certs = target.Certifications
        }
        var assigned *string
        if v, ok := m["assignedLocationId"].(string); ok && v != "" {
                assigned = &v
        } else {
                assigned = target.AssignedLocationID
        }
        if err := h.Store.UpdateUserAccess(userID, roles, quals, certs, active, assigned); err != nil {
                util.WriteError(w, 500, "internal_error", err.Error())
                return
        }
        target, _ = h.Store.GetUser(userID)
        h.audit(u, role, "update_user_access", "user", userID, true, nil)
        util.WriteData(w, 201, userAPI(target))
}

func (h *Handler) ReadUser(w http.ResponseWriter, r *http.Request) {
        u, _, ok := h.requireAuth(w, r)
        if !ok {
                return
        }
        userID := r.PathValue("userId")
        if userID == "" {
                util.WriteError(w, 404, "not_found", "user not found")
                return
        }
        // self or admin/dispatcher
        role := h.activeRole(r)
        if u.ID != userID && role != models.RoleAdministrator && role != models.RoleDispatcher {
                util.WriteError(w, 403, "forbidden", "forbidden")
                return
        }
        target, err := h.Store.GetUser(userID)
        if err != nil {
                util.WriteError(w, 404, "not_found", "user not found")
                return
        }
        util.WriteData(w, 200, userAPI(target))
}

func userAPI(u *models.User) map[string]interface{} {
        out := map[string]interface{}{
                "userId":         u.ID,
                "username":       u.Username,
                "roles":          u.Roles,
                "qualifications": u.Qualifications,
                "certifications": u.Certifications,
                "active":         u.Active,
        }
        if u.Email != nil {
                out["email"] = *u.Email
        }
        if u.FullName != nil {
                out["fullName"] = *u.FullName
        }
        if u.Phone != nil {
                out["phone"] = *u.Phone
        }
        return out
}

func parseCerts(v interface{}) []models.Certification {
        if v == nil {
                return []models.Certification{}
        }
        arr, ok := v.([]interface{})
        if !ok {
                return []models.Certification{}
        }
        var out []models.Certification
        for _, item := range arr {
                m, ok := item.(map[string]interface{})
                if !ok {
                        continue
                }
                c := models.Certification{Code: str(m["code"]), Active: true}
                if a, ok := m["active"].(bool); ok {
                        c.Active = a
                }
                if e, ok := m["expiresAt"].(string); ok && e != "" {
                        c.ExpiresAt = &e
                }
                out = append(out, c)
        }
        return out
}

func toStringSlice(v interface{}) []string {
        if v == nil {
                return []string{}
        }
        switch t := v.(type) {
        case []string:
                return t
        case []interface{}:
                var out []string
                for _, x := range t {
                        out = append(out, str(x))
                }
                return out
        }
        return []string{}
}

func str(v interface{}) string {
        if v == nil {
                return ""
        }
        if s, ok := v.(string); ok {
                return s
        }
        return ""
}

func isNoRows(err error) bool {
        return err == sql.ErrNoRows
}"}

{"path":"/workspace/backend/internal/api/handlers_network.go","command":"create","file_text":"package api

import (
        "net/http"

        "labpd/internal/models"
        "labpd/internal/util"
)

func (h *Handler) CreateLocation(w http.ResponseWriter, r *http.Request) {
        u, role, ok := h.requireRole(w, r, models.RoleAdministrator)
        if !ok {
                return
        }
        m, err := h.decodeJSONMap(r)
        if err != nil {
                util.WriteError(w, 400, "invalid_json", "invalid request body")
                return
        }
        name, _ := m["name"].(string)
        coord, _ := m["coordinate"].(map[string]interface{})
        if name == "" || coord == nil {
                util.WriteError(w, 400, "invalid_coordinate", "name and coordinate required")
                return
        }
        lat, _ := toFloat(coord["latitude"])
        lon, _ := toFloat(coord["longitude"])
        if lat < -90 || lat > 90 || lon < -180 || lon > 180 {
                util.WriteError(w, 400, "invalid_coordinate", "invalid coordinates")
                return
        }
        coverage := 5.0
        if v, ok := toFloat(m["coverageKm"]); ok {
                coverage = v
        }
        if coverage <= 0 || coverage > 5 {
                util.WriteError(w, 400, "invalid_node_coverage", "coverageKm must be >0 and <=5")
                return
        }
        handling := 0
        if v, ok := toFloat(m["handlingMinutes"]); ok {
                handling = int(v)
        }
        if handling < 0 || handling > 1440 {
                util.WriteError(w, 400, "invalid_handling_time", "invalid handling minutes")
                return
        }
        active, _ := m["active"].(bool)
        fns := toStringSlice(m["functions"])
        if len(fns) == 0 {
                util.WriteError(w, 400, "invalid_location_function", "functions required")
                return
        }
        lf := models.LocationFunctions{}
        for _, f := range fns {
                switch f {
                case "collection_point":
                        lf.CollectionPoint = true
                case "transfer_point":
                        lf.TransferPoint = true
                case "hub":
                        lf.Hub = true
                case "laboratory":
                        lf.Laboratory = true
                default:
                        util.WriteError(w, 400, "invalid_location_function", "invalid function: "+f)
                        return
                }
        }
        loc := &models.Location{
                Name: name, Coordinate: models.Coordinate{Latitude: lat, Longitude: lon},
                CoverageKm: coverage, HandlingMinutes: handling, Active: active, Functions: lf,
        }
        if err := h.Store.CreateLocation(loc); err != nil {
                util.WriteError(w, 500, "internal_error", err.Error())
                return
        }
        _ = h.Store.BumpNetworkRevision()
        _ = h.Store.RecomputeServiceabilitySnapshot()
        h.audit(u, role, "create_location", "location", loc.ID, true, nil)
        util.WriteData(w, 201, loc.ToAPI())
}

func (h *Handler) UpdateLocation(w http.ResponseWriter, r *http.Request) {
        u, role, ok := h.requireRole(w, r, models.RoleAdministrator)
        if !ok {
                return
        }
        m, err := h.decodeJSONMap(r)
        if err != nil {
                util.WriteError(w, 400, "invalid_json", "invalid request body")
                return
        }
        id, _ := m["locationId"].(string)
        loc, err := h.Store.GetLocation(id)
        if err != nil {
                util.WriteError(w, 404, "not_found", "location not found")
                return
        }
        if name, ok := m["name"].(string); ok {
                loc.Name = name
        }
        if coord, ok := m["coordinate"].(map[string]interface{}); ok {
                lat, _ := toFloat(coord["latitude"])
                lon, _ := toFloat(coord["longitude"])
                loc.Coordinate = models.Coordinate{Latitude: lat, Longitude: lon}
        }
        if v, ok := toFloat(m["coverageKm"]); ok {
                if v <= 0 || v > 5 {
                        util.WriteError(w, 400, "invalid_node_coverage", "invalid coverage")
                        return
                }
                loc.CoverageKm = v
        }
