func toFloat(v interface{}) (float64, bool) {
        switch t := v.(type) {
        case float64:
                return t, true
        case float32:
                return float64(t), true
        case int:
                return float64(t), true
        case int64:
                return float64(t), true
        case jsonNumber:
                f, err := t.Float64()
                return f, err == nil
        default:
                // json.Number
                if n, ok := v.(interface{ Float64() (float64, error) }); ok {
                        f, err := n.Float64()
                        return f, err == nil
                }
                return 0, false
        }
}

type jsonNumber interface {
        Float64() (float64, error)
}"}

