func (h *Handler) CheckServiceability(w http.ResponseWriter, r *http.Request) {
        u, role, ok := h.requireRole(w, r, models.RoleRequester, models.RoleAdministrator, models.RoleDispatcher)
        if !ok {
                return
        }
        m, err := h.decodeJSONMap(r)
        if err != nil {
                util.WriteError(w, 400, "invalid_json", "invalid body")
                return
        }
        origin, _ := m["origin"].(map[string]interface{})
        if origin == nil {
                util.WriteError(w, 400, "invalid_origin", "origin required")
                return
        }
        lat, _ := toFloat(origin["latitude"])
        lon, _ := toFloat(origin["longitude"])
        originType := "home"
        if v, ok := m["originType"].(string); ok && v != "" {
                originType = v
        }
        var originNodeID *string
        if v, ok := m["originNodeId"].(string); ok && v != "" {
                originNodeID = &v
        }
        stID, _ := m["sampleTypeId"].(string)
        if stID == "" {
                util.WriteError(w, 404, "not_found", "sample type required")
                return
        }
        if _, err := h.Store.GetSampleType(stID); err != nil {
                util.WriteError(w, 404, "not_found", "sample type not found")
                return
        }
        requestedAt, err := util.ParseTime(str(m["requestedAt"]))
        if err != nil || str(m["requestedAt"]) == "" {
                util.WriteError(w, 400, "invalid_time", "invalid requestedAt")
                return
        }
        deadline, err := util.ParseTime(str(m["deliveryDeadline"]))
        if err != nil || str(m["deliveryDeadline"]) == "" {
                util.WriteError(w, 400, "invalid_deadline", "invalid deliveryDeadline")
                return
        }
        var earliest, latest *time.Time
        if v := str(m["earliestCollectionAt"]); v != "" {
                t, e := util.ParseTime(v)
                if e != nil {
                        util.WriteError(w, 400, "invalid_collection_window", "invalid earliest")
                        return
                }
                earliest = &t
        }
        if v := str(m["latestCollectionAt"]); v != "" {
                t, e := util.ParseTime(v)
                if e != nil {
                        util.WriteError(w, 400, "invalid_collection_window", "invalid latest")
                        return
                }
                latest = &t
        }
        if earliest != nil && latest != nil && latest.Before(*earliest) {
                util.WriteError(w, 400, "invalid_collection_window", "latest before earliest")
                return
        }
        result, err := h.Store.CheckServiceability(lat, lon, originType, originNodeID, stID, requestedAt, deadline, earliest, latest)
        if err != nil {
                if err.Error() == "not_found" {
                        util.WriteError(w, 404, "not_found", "not found")
                        return
                }
                util.WriteError(w, 500, "internal_error", err.Error())
                return
        }
        _, ver, _, _, _ := h.Store.GetNetworkMeta()
        out := map[string]interface{}{
                "serviceable":           result.Serviceable,
                "reason":                result.Reason,
                "serviceabilityVersion": ver,
        }
        if result.Serviceable {
                out["targetLaboratoryId"] = result.TargetLaboratoryID
                out["estimatedArrivalAt"] = util.FormatTime(result.EstimatedArrivalAt)
        }
        h.audit(u, role, "check_serviceability", "serviceability", "", true, map[string]interface{}{"serviceable": result.Serviceable})
        util.WriteData(w, 200, out)
}

func (h *Handler) CreateCollectionRequest(w http.ResponseWriter, r *http.Request) {
        u, role, ok := h.requireRole(w, r, models.RoleRequester, models.RoleAdministrator, models.RoleDispatcher)
        if !ok {
                return
        }
        m, err := h.decodeJSONMap(r)
        if err != nil {
                util.WriteError(w, 400, "invalid_json", "invalid body")
                return
        }
        idem := str(m["idempotencyKey"])
        // idempotency optional for create? contract doesn't require it in required list
        if idem != "" {
                if st, body, ok := h.Store.GetIdempotency(idem); ok {
                        w.Header().Set("Content-Type", "application/json")
                        w.WriteHeader(st)
                        _, _ = w.Write(body)
                        return
                }
        }
        requesterID := u.ID
        if v := str(m["requesterId"]); v != "" {
                if role == models.RoleAdministrator || role == models.RoleDispatcher {
                        requesterID = v
                } else if v != u.ID {
                        util.WriteError(w, 403, "forbidden", "cannot create for other requester")
                        return
                }
        }
        sample, err := h.Store.CreateRequestAndSample(m, requesterID, false, nil)
        if err != nil {
                code := err.Error()
                switch code {
                case "not_found":
                        util.WriteError(w, 404, "not_found", "sample type not found")
                case "invalid_time", "invalid_deadline", "invalid_collection_window":
                        util.WriteError(w, 400, code, code)
                default:
                        util.WriteError(w, 500, "internal_error", err.Error())
                }
                return
        }
        // plan journey
        route, err := h.Store.CheckServiceability(sample.OriginLat, sample.OriginLon, sample.OriginType, sample.OriginNodeID,
                sample.SampleTypeID, sample.RequestedAt, sample.DeliveryDeadline, sample.EarliestCollectionAt, sample.LatestCollectionAt)
        if err != nil || route == nil || !route.Serviceable {
                sample.Serviceability = "unserviceable"
                if route != nil {
                        sample.ServiceabilityReason = route.Reason
                } else {
                        sample.ServiceabilityReason = "no_route"
                }
                _ = h.Store.UpdateSample(sample)
                out := collectionRequestResponse(sample, nil, nil)
                if idem != "" {
                        _ = h.Store.SaveIdempotency(idem, u.ID, "create_collection_request", 201, map[string]interface{}{"data": out})
                }
                h.audit(u, role, "create_collection_request", "sample", sample.ID, true, map[string]interface{}{"serviceable": false})
                util.WriteData(w, 201, out)
                return
        }
        journey, assignments, err := h.Store.CreateJourneyForSample(sample, route, false)
        if err != nil {
                util.WriteError(w, 500, "internal_error", err.Error())
                return
        }
        sample, _ = h.Store.GetSample(sample.ID)
        _, _ = h.Store.AddTimeline("request_created", u.ID, role, "sample", sample.ID, true, map[string]interface{}{"requestId": sample.RequestID}, &sample.ID, &journey.ID)
        _, _ = h.Store.AddRealtimeEvent("sample_created", "sample", sample.ID, map[string]interface{}{"state": sample.State})
        out := collectionRequestResponse(sample, journey, assignments)
        if idem != "" {
                _ = h.Store.SaveIdempotency(idem, u.ID, "create_collection_request", 201, map[string]interface{}{"data": out})
        }
        h.audit(u, role, "create_collection_request", "sample", sample.ID, true, nil)
        util.WriteData(w, 201, out)
}

func (h *Handler) IngestPresealedSample(w http.ResponseWriter, r *http.Request) {
        u, role, ok := h.requireRole(w, r,
                models.RoleCollectionProfessional, models.RoleDeliveryPartner,
                models.RoleNodeHandler, models.RoleLaboratoryTeam,
                models.RoleAdministrator, models.RoleDispatcher)
        if !ok {
                return
        }
        m, err := h.decodeJSONMap(r)
        if err != nil {
                util.WriteError(w, 400, "invalid_json", "invalid body")
                return
        }
        originType := "node"
        if v, ok := m["originType"].(string); ok && v != "" {
                originType = v
        }
        if originType == "home" {
                util.WriteError(w, 400, "invalid_origin_type", "presealed cannot originate from home")
                return
        }
        m["originType"] = originType
        idem := str(m["idempotencyKey"])
        if idem != "" {
                if st, body, ok := h.Store.GetIdempotency(idem); ok {
                        w.Header().Set("Content-Type", "application/json")
                        w.WriteHeader(st)
                        _, _ = w.Write(body)
                        return
                }
        }
        holderID := u.ID
        requesterID := u.ID
        if v := str(m["requesterId"]); v != "" {
                requesterID = v
        }
        sample, err := h.Store.CreateRequestAndSample(m, requesterID, true, &holderID)
        if err != nil {
                util.WriteError(w, 400, err.Error(), err.Error())
                return
        }
        route, err := h.Store.CheckServiceability(sample.OriginLat, sample.OriginLon, sample.OriginType, sample.OriginNodeID,
                sample.SampleTypeID, sample.RequestedAt, sample.DeliveryDeadline, sample.EarliestCollectionAt, sample.LatestCollectionAt)
        var journey *models.Journey
        var assignments []*models.Assignment
        if route != nil && route.Serviceable {
                journey, assignments, err = h.Store.CreateJourneyForSample(sample, route, true)
                if err != nil {
                        util.WriteError(w, 500, "internal_error", err.Error())
                        return
                }
        } else {
                sample.Serviceability = "unserviceable"
                if route != nil {
                        sample.ServiceabilityReason = route.Reason
                }
                _ = h.Store.UpdateSample(sample)
        }
        sample, _ = h.Store.GetSample(sample.ID)
        out := collectionRequestResponse(sample, journey, assignments)
        out["alreadySealed"] = true
        if idem != "" {
                _ = h.Store.SaveIdempotency(idem, u.ID, "ingest_presealed_sample", 201, map[string]interface{}{"data": out})
        }
        h.audit(u, role, "ingest_presealed_sample", "sample", sample.ID, true, nil)
        util.WriteData(w, 201, out)
}

func collectionRequestResponse(sample *models.Sample, journey *models.Journey, assignments []*models.Assignment) map[string]interface{} {
        activeIDs := []string{}
        for _, a := range assignments {
                if a.Active && (a.Status == "offered" || a.Status == "accepted" || a.Status == "in_progress" || a.Status == "pending") {
                        if a.Status == "offered" || a.Status == "accepted" || a.Status == "in_progress" {
                                activeIDs = append(activeIDs, a.ID)
                        }
                }
        }
        // include first offered
        for _, a := range assignments {
                if a.Status == "offered" {
                        found := false
                        for _, id := range activeIDs {
                                if id == a.ID {
                                        found = true
                                }
                        }
                        if !found {
                                activeIDs = append(activeIDs, a.ID)
                        }
                }
        }
        out := map[string]interface{}{
                "requestId":           sample.RequestID,
                "sampleId":            sample.ID,
                "serviceability":      sample.Serviceability,
                "serviceabilityReason": sample.ServiceabilityReason,
                "activeAssignmentIds": activeIDs,
                "alreadySealed":       sample.AlreadySealed,
        }
        if sample.EarliestCollectionAt != nil {
                out["earliestCollectionAt"] = util.FormatTime(*sample.EarliestCollectionAt)
        }
        if sample.LatestCollectionAt != nil {
                out["latestCollectionAt"] = util.FormatTime(*sample.LatestCollectionAt)
        }
        if journey != nil {
                out["journeyId"] = journey.ID
        }
