func (h *Handler) CollectAndSealSample(w http.ResponseWriter, r *http.Request) {
        u, role, ok := h.requireRole(w, r, models.RoleCollectionProfessional, models.RoleAdministrator)
        if !ok {
                return
        }
        m, err := h.decodeJSONMap(r)
        if err != nil {
                util.WriteError(w, 400, "invalid_json", "invalid body")
                return
        }
        idem := str(m["idempotencyKey"])
        if idem == "" {
                util.WriteError(w, 400, "idempotency_required", "idempotency required")
                return
        }
        if st, body, ok := h.Store.GetIdempotency(idem); ok {
                w.Header().Set("Content-Type", "application/json")
                w.WriteHeader(st)
                _, _ = w.Write(body)
                return
        }
        sampleID := str(m["sampleId"])
        assignmentID := str(m["assignmentId"])
        sm, err := h.Store.GetSample(sampleID)
        if err != nil {
                util.WriteError(w, 404, "not_found", "sample not found")
                return
        }
        asg, err := h.Store.GetAssignment(assignmentID)
        if err != nil || !asg.Active {
                util.WriteError(w, 409, "assignment_inactive", "assignment inactive")
                return
        }
        if asg.Kind != "collection" {
                util.WriteError(w, 409, "invalid_assignment", "not a collection assignment")
                return
        }
        if asg.WorkerID == nil || *asg.WorkerID != u.ID {
                if role != models.RoleAdministrator {
                        util.WriteError(w, 403, "forbidden", "not assigned worker")
                        return
                }
        }
        if asg.Status != "accepted" && asg.Status != "in_progress" {
                util.WriteError(w, 409, "collection_not_ready", "assignment not ready")
                return
        }
        collectedAt, err := util.ParseTime(str(m["collectedAt"]))
        if err != nil {
                util.WriteError(w, 400, "invalid_time", "invalid collectedAt")
                return
        }
        // collection window
        if sm.EarliestCollectionAt != nil && collectedAt.Before(*sm.EarliestCollectionAt) {
                util.WriteError(w, 409, "outside_collection_window", "before window")
                return
        }
        if sm.LatestCollectionAt != nil && collectedAt.After(*sm.LatestCollectionAt) {
                util.WriteError(w, 409, "outside_collection_window", "after window")
                return
        }
        container := str(m["containerType"])
        temp, _ := toFloat(m["observedTemperatureC"])
        compliant := true
        if container != sm.ContainerType {
                compliant = false
        }
        if temp < sm.TemperatureMinC || temp > sm.TemperatureMaxC {
                compliant = false
        }
        // certification check
        st, _ := h.Store.GetSampleType(sm.SampleTypeID)
        if st != nil && st.QualifiedCollectorRequired {
                okCert := false
                for _, q := range u.Qualifications {
                        if q == st.RequiredQualification || q == st.Name {
                                okCert = true
                        }
                }
                for _, c := range u.Certifications {
                        if c.Active && (c.Code == st.RequiredQualification || c.Code == st.Name) {
                                okCert = true
                        }
                }
                if !okCert && role != models.RoleAdministrator {
                        util.WriteError(w, 409, "certification_inactive", "missing certification")
                        return
                }
        }
        now := collectedAt
        sm.Sealed = true
        sm.SealedAt = &now
        sm.State = "sealed"
        sm.CurrentHolderID = &u.ID
        sm.LocationRecordedAt = &now
        if !compliant {
                code := "handling_noncompliant"
                sm.ExceptionCode = &code
                msg := "observed handling outside required range"
                sm.ExceptionMessage = &msg
        }
        _ = h.Store.UpdateSample(sm)
        asg.Status = "completed"
        asg.CompletedAt = &now
        _ = h.Store.UpdateAssignment(asg)

        // offer next transport assignment
        if sm.ActiveJourneyID != nil {
                asgs, _ := h.Store.ListAssignmentsByJourney(*sm.ActiveJourneyID)
                for _, a := range asgs {
                        if a.Kind == "transport" && a.Status == "pending" && a.Active {
                                a.Status = "offered"
                                exp := util.Now().Add(time.Duration(models.OfferTimeoutSeconds) * time.Second)
                                a.OfferExpiresAt = &exp
                                worker := h.Store.FindEligibleWorkerPublic("delivery_partner", "", nil)
                                if worker != nil {
                                        a.OfferedTo = &worker.ID
                                }
                                _ = h.Store.UpdateAssignment(a)
                                break
                        }
                }
        }
        _, _ = h.Store.AddTimeline("collect_and_seal", u.ID, role, "sample", sm.ID, true, map[string]interface{}{"compliant": compliant}, &sm.ID, sm.ActiveJourneyID)
        out := map[string]interface{}{
                "sampleId":          sm.ID,
                "status":            "sealed",
                "currentHolderId":   u.ID,
                "sealedAt":          util.FormatTime(now),
                "handlingCompliant": compliant,
        }
        _ = h.Store.SaveIdempotency(idem, u.ID, "collect_and_seal_sample", 201, map[string]interface{}{"data": out})
        h.audit(u, role, "collect_and_seal_sample", "sample", sm.ID, true, nil)
        util.WriteData(w, 201, out)
}

func (h *Handler) RecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
        u, role, ok := h.requireRole(w, r,
                models.RoleCollectionProfessional, models.RoleDeliveryPartner,
                models.RoleNodeHandler, models.RoleLaboratoryTeam, models.RoleAdministrator)
        if !ok {
                return
        }
        m, err := h.decodeJSONMap(r)
        if err != nil {
                util.WriteError(w, 400, "invalid_json", "invalid body")
                return
        }
        sampleID := str(m["sampleId"])
        sm, err := h.Store.GetSample(sampleID)
        if err != nil {
                util.WriteError(w, 404, "not_found", "not found")
                return
        }
        if sm.CurrentHolderID == nil || *sm.CurrentHolderID != u.ID {
                if role != models.RoleAdministrator {
                        util.WriteError(w, 409, "not_current_holder", "not current holder")
                        return
                }
        }
        container := str(m["containerType"])
        temp, _ := toFloat(m["observedTemperatureC"])
        compliant := container == sm.ContainerType && temp >= sm.TemperatureMinC && temp <= sm.TemperatureMaxC
        if !compliant {
                code := "handling_noncompliant"
                sm.ExceptionCode = &code
                msg := "checkpoint outside range"
                sm.ExceptionMessage = &msg
                sm.State = "exception"
                _ = h.Store.UpdateSample(sm)
                _, _ = h.Store.DB.SQL.Exec(`INSERT INTO exceptions (id, sample_id, code, message) VALUES ($1,$2,$3,$4)`,
                        util.NewID(), sm.ID, code, msg)
        }
        _, _ = h.Store.AddTimeline("handling_checkpoint", u.ID, role, "sample", sm.ID, true, map[string]interface{}{
                "containerType": container, "temperature": temp, "compliant": compliant,
        }, &sm.ID, sm.ActiveJourneyID)
        h.audit(u, role, "record_handling_checkpoint", "sample", sm.ID, true, nil)
        util.WriteData(w, 201, map[string]interface{}{
                "sampleId": sm.ID, "handlingCompliant": compliant, "exception": !compliant,
        })
}

func (h *Handler) ConfirmLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
        u, role, ok := h.requireRole(w, r, models.RoleLaboratoryTeam, models.RoleAdministrator)
        if !ok {
                return
        }
        m, err := h.decodeJSONMap(r)
        if err != nil {
