        if err != nil {
                util.WriteError(w, 404, "not_found", "not found")
                return
        }
        if role == models.RoleLaboratoryTeam {
                if u.AssignedLocationID == nil || *u.AssignedLocationID != labID {
                        util.WriteError(w, 409, "wrong_laboratory_operator", "wrong lab")
                        return
                }
        }
        if sm.TargetLaboratoryID != nil && *sm.TargetLaboratoryID != labID {
                util.WriteError(w, 409, "wrong_laboratory", "wrong laboratory")
                return
        }
        receivedAt, err := util.ParseTime(str(m["receivedAt"]))
        if err != nil {
                util.WriteError(w, 400, "invalid_receipt_time", "invalid time")
                return
        }
        sm.State = "received"
        sm.ReceivedLaboratoryID = &labID
        sm.CurrentHolderID = &u.ID
        _ = h.Store.UpdateSample(sm)
        if sm.ActiveJourneyID != nil {
                j, _ := h.Store.GetJourney(*sm.ActiveJourneyID)
                if j != nil {
                        j.Status = "completed"
                        _ = h.Store.UpdateJourney(j)
                }
                asgs, _ := h.Store.ListAssignmentsByJourney(*sm.ActiveJourneyID)
                for _, a := range asgs {
                        if a.Kind == "laboratory" && a.Active {
                                a.Status = "completed"
                                a.WorkerID = &u.ID
                                a.CompletedAt = &receivedAt
                                _ = h.Store.UpdateAssignment(a)
                        }
                }
                _ = h.Store.ReleaseCapacityForJourneyPublic(*sm.ActiveJourneyID)
        }
        _, _ = h.Store.AddTimeline("laboratory_receipt", u.ID, role, "sample", sm.ID, true, map[string]interface{}{"laboratoryId": labID}, &sm.ID, sm.ActiveJourneyID)
        out := map[string]interface{}{
                "sampleId": sampleID, "laboratoryId": labID, "status": "received", "receivedAt": util.FormatTime(receivedAt),
        }
        _ = h.Store.SaveIdempotency(idem, u.ID, "confirm_laboratory_receipt", 201, map[string]interface{}{"data": out})
        h.audit(u, role, "confirm_laboratory_receipt", "sample", sm.ID, true, nil)
        util.WriteData(w, 201, out)
}

