func (h *Handler) ReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
        _, _, ok := h.requireAuth(w, r)
        if !ok {
                return
        }
        ctx := context.Background()
        opts := options.FindOne().SetSort(bson.D{{Key: "version", Value: -1}})
        var doc bson.M
        err := h.Store.DB.MongoDB.Collection("serviceability_snapshots").FindOne(ctx, bson.M{"status": "complete"}, opts).Decode(&doc)
        if err != nil {
                rev, ver, status, at, _ := h.Store.GetNetworkMeta()
                util.WriteData(w, 200, map[string]interface{}{
                        "version": ver, "status": status, "computedAt": util.FormatTime(at),
                        "networkRevision": rev, "regions": []interface{}{}, "activeCollectionPointCount": 0,
                })
                return
        }
        regions := []interface{}{}
        if rgs, ok := doc["regions"].(bson.A); ok {
                for _, rg := range rgs {
                        regions = append(regions, rg)
                }
        }
        ver := 1
        if v, ok := doc["version"].(int32); ok {
                ver = int(v)
        } else if v, ok := doc["version"].(int64); ok {
                ver = int(v)
        } else if v, ok := doc["version"].(int); ok {
                ver = v
        }
        rev := int64(0)
        if v, ok := doc["networkRevision"].(int64); ok {
                rev = v
        } else if v, ok := doc["networkRevision"].(int32); ok {
                rev = int64(v)
        }
        at := util.Now()
        if t, ok := doc["computedAt"].(time.Time); ok {
                at = t
        }
        acp := 0
        if v, ok := doc["activeCollectionPointCount"].(int32); ok {
                acp = int(v)
        } else if v, ok := doc["activeCollectionPointCount"].(int64); ok {
                acp = int(v)
        }
        util.WriteData(w, 200, map[string]interface{}{
                "version": ver, "status": "complete", "computedAt": util.FormatTime(at),
                "networkRevision": rev, "regions": regions, "activeCollectionPointCount": acp,
        })
}

