func (s *Store) ListJourneys() ([]*models.Journey, error) {
        rows, err := s.DB.SQL.Query(`SELECT id FROM journeys ORDER BY created_at DESC`)
        if err != nil {
                return nil, err
        }
        defer rows.Close()
        var out []*models.Journey
