}

func (s *Store) ApplyDeclinePenalty(workerID string) {
        _, _ = s.DB.SQL.Exec(`UPDATE users SET decline_penalty_until = now() + interval '30 minutes' WHERE id=$1`, workerID)
}

func (s *Store) ExpireStaleOffers() {
        rows, err := s.DB.SQL.Query(`SELECT id FROM assignments WHERE status='offered' AND offer_expires_at IS NOT NULL AND offer_expires_at < now() AND active=true`)
        if err != nil {
                return
        }
        defer rows.Close()
        for rows.Next() {
                var id string
                _ = rows.Scan(&id)
                a, err := s.GetAssignment(id)
                if err != nil {
                        continue
                }
                // treat as declined and re-offer
                a.Status = "declined"
                declinedTo := a.OfferedTo
                a.OfferedTo = nil
                a.Active = false
                _ = s.UpdateAssignment(a)
                if declinedTo != nil {
                        s.ApplyDeclinePenalty(*declinedTo)
                }
                // create new offer
                newA := *a
                newA.ID = newID()
                newA.Status = "offered"
                newA.Active = true
                newA.WorkerID = nil
                exp := now().Add(offerTimeout())
                newA.OfferExpiresAt = &exp
                role := "delivery_partner"
                if a.Kind == "collection" {
                        role = "collection_professional"
                } else if a.Kind == "node" {
                        role = "node_handler"
                } else if a.Kind == "laboratory" {
                        role = "laboratory_team"
                }
                var loc *string
                if a.NodeID != nil {
                        loc = a.NodeID
                }
                if a.LaboratoryID != nil {
                        loc = a.LaboratoryID
                }
                stID := ""
                if a.SampleID != nil {
                        if sm, err := s.GetSample(*a.SampleID); err == nil {
                                stID = sm.SampleTypeID
                        }
                }
                exclude := map[string]bool{}
                if declinedTo != nil {
                        exclude[*declinedTo] = true
                }
                w := s.findEligibleWorker(role, stID, loc, exclude)
                if w != nil {
                        newA.OfferedTo = &w.ID
                }
                _ = s.insertAssignment(&newA)
        }
}

func ns(v interface{}) *string {
        if v == nil {
                return nil
        }
        switch t := v.(type) {
        case string:
                return &t
        case []byte:
                s := string(t)
                return &s
        default:
                return nil
        }
}

func nt(v interface{}) *time.Time {
        if v == nil {
                return nil
        }
        if t, ok := v.(time.Time); ok {
                return &t
        }
        return nil
}

func newID() string {
        return utilNewID()
}

func now() time.Time { return utilNow() }

func offerTimeout() time.Duration {
        return time.Duration(models.OfferTimeoutSeconds) * time.Second
}

