func (h *Handler) AcceptAssignment(w http.ResponseWriter, r *http.Request) {
        u, role, ok := h.requireAuth(w, r)
        if !ok {
                return
        }
        if role == "" {
                util.WriteError(w, 409, "role_not_selected", "role required")
                return
        }
        m, err := h.decodeJSONMap(r)
        if err != nil {
                util.WriteError(w, 400, "invalid_json", "invalid body")
                return
        }
        idem := str(m["idempotencyKey"])
        if idem == "" {
                util.WriteError(w, 400, "idempotency_required", "required")
                return
        }
        if st, body, ok := h.Store.GetIdempotency(idem); ok {
                w.Header().Set("Content-Type", "application/json")
                w.WriteHeader(st)
                _, _ = w.Write(body)
                return
        }
        assignmentID := str(m["assignmentId"])
        asg, err := h.Store.GetAssignment(assignmentID)
        if err != nil {
                util.WriteError(w, 404, "not_found", "not found")
                return
        }
        if !asg.Active {
                util.WriteError(w, 409, "assignment_inactive", "inactive")
                return
        }
        if asg.Status != "offered" {
                if asg.Status == "accepted" && asg.WorkerID != nil && *asg.WorkerID == u.ID {
                        out := map[string]interface{}{"assignmentId": asg.ID, "workerId": u.ID, "status": "accepted"}
                        util.WriteData(w, 201, out)
                        return
                }
                util.WriteError(w, 409, "offer_not_available", "not offered")
                return
        }
        if asg.OfferedTo == nil || *asg.OfferedTo != u.ID {
                if role != models.RoleAdministrator {
                        util.WriteError(w, 409, "offer_not_offered", "not offered to you")
                        return
                }
        }
        if asg.OfferExpiresAt != nil && util.Now().After(*asg.OfferExpiresAt) {
                util.WriteError(w, 409, "offer_not_available", "offer expired")
                return
        }
        now := util.Now()
        asg.Status = "accepted"
        asg.WorkerID = &u.ID
        asg.AcceptedAt = &now
        _ = h.Store.UpdateAssignment(asg)
        h.Store.IncrementWorkerAssignments(u.ID)
        if asg.JourneyID != "" {
                j, _ := h.Store.GetJourney(asg.JourneyID)
                if j != nil {
                        found := false
                        for _, wid := range j.AssignedWorkerIDs {
                                if wid == u.ID {
                                        found = true
                                }
                        }
                        if !found {
                                j.AssignedWorkerIDs = append(j.AssignedWorkerIDs, u.ID)
                                _ = h.Store.UpdateJourney(j)
                        }
                }
        }
        _, _ = h.Store.AddTimeline("accept_assignment", u.ID, role, "assignment", asg.ID, true, nil, asg.SampleID, &asg.JourneyID)
        out := map[string]interface{}{"assignmentId": asg.ID, "workerId": u.ID, "status": "accepted"}
        _ = h.Store.SaveIdempotency(idem, u.ID, "accept_assignment", 201, map[string]interface{}{"data": out})
        h.audit(u, role, "accept_assignment", "assignment", asg.ID, true, nil)
        util.WriteData(w, 201, out)
}

func (h *Handler) DeclineAssignment(w http.ResponseWriter, r *http.Request) {
