        _, err = h.Store.DB.SQL.Exec(`INSERT INTO assignments (id, journey_id, sample_id, sample_ids, kind, status, sequence, from_location_id, to_location_id, node_id, laboratory_id, worker_id, offered_to, offer_expires_at, expected_sample_type_id, incoming_from_location_id, outgoing_to_location_id, active)
