                newA.FromLocationID, newA.ToLocationID, newA.NodeID, newA.LaboratoryID, newA.WorkerID, newA.OfferedTo, newA.OfferExpiresAt,
                newA.ExpectedSampleTypeID, newA.IncomingFromLocationID, newA.OutgoingToLocationID, newA.Active)
