func (h *Handler) UpdateAssignmentProgress(w http.ResponseWriter, r *http.Request) {
        u, role, ok := h.requireAuth(w, r)
        if !ok {
                return
        }
        m, err := h.decodeJSONMap(r)
        if err != nil {
                util.WriteError(w, 400, "invalid_json", "invalid body")
                return
        }
        idem := str(m["idempotencyKey"])
        if idem == "" {
                util.WriteError(w, 400, "idempotency_required", "required")
                return
        }
        if st, body, ok := h.Store.GetIdempotency(idem); ok {
                w.Header().Set("Content-Type", "application/json")
                w.WriteHeader(st)
                _, _ = w.Write(body)
                return
        }
        assignmentID := str(m["assignmentId"])
        status := str(m["status"])
        asg, err := h.Store.GetAssignment(assignmentID)
        if err != nil || !asg.Active {
                util.WriteError(w, 409, "assignment_inactive", "inactive")
                return
        }
        if asg.WorkerID == nil || *asg.WorkerID != u.ID {
                if role != models.RoleAdministrator && role != models.RoleDispatcher {
                        util.WriteError(w, 403, "ineligible_worker", "not your assignment")
                        return
                }
        }
        occurredAt, err := util.ParseTime(str(m["occurredAt"]))
        if err != nil {
                util.WriteError(w, 400, "invalid_time", "invalid time")
                return
        }
        // collection must be done before transport progress beyond certain points
        if asg.Kind == "transport" && asg.SampleID != nil {
                sm, _ := h.Store.GetSample(*asg.SampleID)
                if sm != nil && !sm.Sealed && (status == "picked_up" || status == "in_transit" || status == "delivered") {
                        util.WriteError(w, 409, "collection_required", "sample not sealed")
                        return
                }
                if sm != nil && sm.CurrentHolderID != nil && *sm.CurrentHolderID != u.ID && status != "at_pickup" {
                        // may need custody
                }
        }
        asg.Status = status
        if status == "completed" || status == "delivered" {
                asg.Status = "completed"
                asg.CompletedAt = &occurredAt
                if asg.SampleID != nil {
                        sm, _ := h.Store.GetSample(*asg.SampleID)
                        if sm != nil {
                                sm.State = status
                                if status == "delivered" || status == "completed" {
                                        sm.State = "delivered"
                                }
                                sm.CurrentHolderID = &u.ID
                                _ = h.Store.UpdateSample(sm)
                        }
                }
        } else if status == "in_progress" || status == "in_transit" || status == "picked_up" {
                if asg.SampleID != nil {
                        sm, _ := h.Store.GetSample(*asg.SampleID)
                        if sm != nil {
                                sm.State = status
                                sm.CurrentHolderID = &u.ID
                                _ = h.Store.UpdateSample(sm)
                        }
                }
        }
        _ = h.Store.UpdateAssignment(asg)
        sampleID := ""
        if asg.SampleID != nil {
                sampleID = *asg.SampleID
        }
        _, _ = h.Store.AddTimeline("assignment_progress", u.ID, role, "assignment", asg.ID, true, map[string]interface{}{"status": status}, asg.SampleID, &asg.JourneyID)
        out := map[string]interface{}{"assignmentId": asg.ID, "sampleId": sampleID, "status": asg.Status}
        _ = h.Store.SaveIdempotency(idem, u.ID, "update_assignment_progress", 201, map[string]interface{}{"data": out})
        h.audit(u, role, "update_assignment_progress", "assignment", asg.ID, true, nil)
        util.WriteData(w, 201, out)
}

func (h *Handler) InitiateHandoff(w http.ResponseWriter, r *http.Request) {
        u, role, ok := h.requireAuth(w, r)
        if !ok {
                return
        }
        m, err := h.decodeJSONMap(r)
        if err != nil {
                util.WriteError(w, 400, "invalid_json", "invalid body")
                return
        }
        idem := str(m["idempotencyKey"])
        sampleID := str(m["sampleId"])
        receiverID := str(m["receiverId"])
        sm, err := h.Store.GetSample(sampleID)
        if err != nil {
                util.WriteError(w, 404, "not_found", "not found")
                return
        }
        if sm.CurrentHolderID == nil || *sm.CurrentHolderID != u.ID {
                if role != models.RoleAdministrator {
                        util.WriteError(w, 409, "not_current_holder", "not holder")
                        return
                }
        }
        if sm.PendingHandoffID != nil {
                util.WriteError(w, 409, "pending_handoff_exists", "pending handoff exists")
                return
        }
        if _, err := h.Store.GetUser(receiverID); err != nil {
                util.WriteError(w, 400, "invalid_receiver", "receiver not found")
                return
        }
        ho := &models.Handoff{
                ID: util.NewID(), SampleID: sampleID, SenderID: u.ID, ReceiverID: receiverID, Status: "pending",
        }
        if v := str(m["fromAssignmentId"]); v != "" {
                ho.FromAssignmentID = &v
        }
        if v := str(m["toAssignmentId"]); v != "" {
                ho.ToAssignmentID = &v
        }
        if err := h.Store.InsertHandoff(ho); err != nil {
                util.WriteError(w, 500, "internal_error", err.Error())
                return
        }
        sm.PendingHandoffID = &ho.ID
        _ = h.Store.UpdateSample(sm)
        out := map[string]interface{}{
                "handoffId": ho.ID, "sampleId": sampleID, "senderId": u.ID, "receiverId": receiverID, "status": "pending",
        }
        if idem != "" {
                _ = h.Store.SaveIdempotency(idem, u.ID, "initiate_handoff", 201, map[string]interface{}{"data": out})
        }
        h.audit(u, role, "initiate_handoff", "handoff", ho.ID, true, nil)
        util.WriteData(w, 201, out)
}

func (h *Handler) ConfirmHandoff(w http.ResponseWriter, r *http.Request) {
        u, role, ok := h.requireAuth(w, r)
        if !ok {
                return
        }
        m, err := h.decodeJSONMap(r)
        if err != nil {
                util.WriteError(w, 400, "invalid_json", "invalid body")
                return
        }
        idem := str(m["idempotencyKey"])
        handoffID := str(m["handoffId"])
        side := str(m["side"]) // sender | receiver
        if side == "" {
                if str(m["confirmationSide"]) != "" {
                        side = str(m["confirmationSide"])
                }
        }
        ho, err := h.Store.GetHandoff(handoffID)
        if err != nil {
                util.WriteError(w, 404, "not_found", "not found")
                return
        }
        if ho.Status == "completed" {
                out := map[string]interface{}{
                        "handoffId": ho.ID, "senderId": ho.SenderID, "receiverId": ho.ReceiverID,
                        "currentHolderId": ho.ReceiverID, "status": "completed",
                }
                util.WriteData(w, 201, out)
                return
        }
        if ho.Status != "pending" {
                util.WriteError(w, 409, "handoff_inactive", "inactive")
                return
        }
        now := util.Now()
        if side == "sender" || u.ID == ho.SenderID && side == "" {
                if u.ID != ho.SenderID && role != models.RoleAdministrator {
                        util.WriteError(w, 409, "invalid_sender", "not sender")
                        return
                }
                ho.SenderConfirmed = true
                ho.SenderConfirmedAt = &now
                side = "sender"
        } else if side == "receiver" || u.ID == ho.ReceiverID {
                if u.ID != ho.ReceiverID && role != models.RoleAdministrator {
                        util.WriteError(w, 409, "invalid_receiver", "not receiver")
                        return
                }
                ho.ReceiverConfirmed = true
                ho.ReceiverConfirmedAt = &now
                side = "receiver"
        } else {
                util.WriteError(w, 400, "invalid_confirmation_side", "side required")
                return
        }
        // auto-confirm if only one side needed? contract requires both
        if ho.SenderConfirmed && ho.ReceiverConfirmed {
                ho.Status = "completed"
                ho.CompletedAt = &now
                sm, _ := h.Store.GetSample(ho.SampleID)
                if sm != nil {
                        sm.CurrentHolderID = &ho.ReceiverID
                        sm.PendingHandoffID = nil
                        _ = h.Store.UpdateSample(sm)
                }
        }
        _ = h.Store.UpdateHandoff(ho)
        currentHolder := ho.SenderID
        if ho.Status == "completed" {
                currentHolder = ho.ReceiverID
        }
        out := map[string]interface{}{
                "handoffId": ho.ID, "senderId": ho.SenderID, "receiverId": ho.ReceiverID,
                "currentHolderId": currentHolder, "status": ho.Status,
        }
        if idem != "" {
                _ = h.Store.SaveIdempotency(idem, u.ID, "confirm_handoff", 201, map[string]interface{}{"data": out})
        }
        h.audit(u, role, "confirm_handoff", "handoff", ho.ID, true, map[string]interface{}{"side": side})
        util.WriteData(w, 201, out)
}

func (h *Handler) RecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
        u, role, ok := h.requireAuth(w, r)
        if !ok {
                return
        }
        m, err := h.decodeJSONMap(r)
        if err != nil {
                util.WriteError(w, 400, "invalid_json", "invalid body")
                return
        }
        workerID := str(m["workerId"])
        if workerID == "" {
                workerID = u.ID
        }
        if workerID != u.ID && role != models.RoleAdministrator && role != models.RoleDispatcher {
                util.WriteError(w, 403, "forbidden", "cannot update other worker")
                return
        }
        coord, _ := m["coordinate"].(map[string]interface{})
        if coord == nil {
                // try latitude/longitude top-level
                lat, ok1 := toFloat(m["latitude"])
                lon, ok2 := toFloat(m["longitude"])
                if !ok1 || !ok2 {
                        util.WriteError(w, 400, "invalid_coordinate", "coordinate required")
                        return
                }
                coord = map[string]interface{}{"latitude": lat, "longitude": lon}
        }
        lat, _ := toFloat(coord["latitude"])
        lon, _ := toFloat(coord["longitude"])
        at := util.Now()
        if v := str(m["recordedAt"]); v != "" {
                if t, e := util.ParseTime(v); e == nil {
                        at = t
                }
        }
        _ = h.Store.RecordWorkerLocation(workerID, lat, lon, at)
        // update samples held by worker
        samples, _ := h.Store.ListSamples()
        for _, sm := range samples {
                if sm.CurrentHolderID != nil && *sm.CurrentHolderID == workerID {
                        sm.LocationLat = &lat
                        sm.LocationLon = &lon
                        sm.LocationRecordedAt = &at
                        _ = h.Store.UpdateSample(sm)
                }
        }
        h.audit(u, role, "record_worker_location", "worker", workerID, true, nil)
        util.WriteData(w, 200, map[string]interface{}{
                "workerId": workerID,
                "coordinate": map[string]interface{}{"latitude": lat, "longitude": lon},
                "recordedAt": util.FormatTime(at),
        })
}

func (h *Handler) SetWorkerAvailability(w http.ResponseWriter, r *http.Request) {
        u, role, ok := h.requireAuth(w, r)
        if !ok {
                return
        }
        m, err := h.decodeJSONMap(r)
        if err != nil {
                util.WriteError(w, 400, "invalid_json", "invalid body")
                return
        }
        workerID := str(m["workerId"])
        if workerID != u.ID && role != models.RoleAdministrator && role != models.RoleDispatcher {
                util.WriteError(w, 403, "forbidden", "forbidden")
                return
        }
        available, _ := m["available"].(bool)
        capF, okc := toFloat(m["capacityUnits"])
        if !okc || capF < 0 {
                util.WriteError(w, 400, "invalid_capacity", "invalid capacity")
                return
        }
        if _, err := h.Store.GetUser(workerID); err != nil {
                util.WriteError(w, 404, "not_found", "not found")
                return
        }
        _ = h.Store.SetWorkerAvailability(workerID, available, int(capF))
        h.audit(u, role, "set_worker_availability", "worker", workerID, true, nil)
        util.WriteData(w, 200, map[string]interface{}{"workerId": workerID, "available": available, "capacityUnits": int(capF)})
}

func (h *Handler) ListRoleWork(w http.ResponseWriter, r *http.Request) {
        u, activeRole, ok := h.requireAuth(w, r)
        if !ok {
                return
        }
        m, _ := h.decodeJSONMap(r)
        role := activeRole
        if v := str(m["role"]); v != "" {
                role = v
        }
        if role == "" {
                util.WriteError(w, 409, "role_not_selected", "role required")
                return
        }
        pending := []interface{}{}
        inProgress := []interface{}{}
        completed := []interface{}{}

        switch role {
        case models.RoleRequester:
                samples, _ := h.Store.ListSamplesByRequester(u.ID)
                for _, sm := range samples {
                        item := sampleWorkItem(sm)
                        switch {
                        case sm.State == "received" || sm.State == "cancelled" || sm.State == "expired":
                                completed = append(completed, item)
                        case sm.State == "requested" || sm.State == "planned":
                                pending = append(pending, item)
                        default:
                                inProgress = append(inProgress, item)
                        }
                }
        case models.RoleDispatcher, models.RoleAdministrator:
                samples, _ := h.Store.ListSamples()
                for _, sm := range samples {
                        item := sampleWorkItem(sm)
                        switch {
                        case sm.State == "received" || sm.State == "cancelled" || sm.State == "expired":
                                completed = append(completed, item)
                        case sm.State == "requested" || sm.State == "planned":
                                pending = append(pending, item)
                        default:
                                inProgress = append(inProgress, item)
                        }
                }
                journeys, _ := h.Store.ListJourneys()
                for _, j := range journeys {
                        item := journeyWorkItem(j)
                        switch j.Status {
                        case "completed", "cancelled":
                                completed = append(completed, item)
                        case "planned":
                                pending = append(pending, item)
                        default:
                                inProgress = append(inProgress, item)
                        }
                }
        default:
                asgs, _ := h.Store.ListAssignmentsForWorker(u.ID)
                for _, a := range asgs {
                        item := assignmentWorkItem(a)
                        switch a.Status {
                        case "completed", "declined", "cancelled":
                                completed = append(completed, item)
                        case "offered", "pending":
                                pending = append(pending, item)
                        default:
                                inProgress = append(inProgress, item)
                        }
                }
        }
        util.WriteData(w, 200, map[string]interface{}{
                "pending": pending, "inProgress": inProgress, "completed": completed,
        })
}

func sampleWorkItem(sm *models.Sample) map[string]interface{} {
        hist, _ := ([]models.TimelineEntry)(nil), error(nil)
        item := map[string]interface{}{
                "kind":          "sample",
                "sampleId":      sm.ID,
                "requestId":     sm.RequestID,
                "status":        sm.State,
                "history":       hist,
                "locationStale": locationStale(sm),
        }
        if hist == nil {
                item["history"] = []interface{}{}
        }
        item["serviceability"] = sm.Serviceability
        item["requestedAt"] = util.FormatTime(sm.RequestedAt)
        item["deliveryDeadline"] = util.FormatTime(sm.DeliveryDeadline)
        if sm.ActiveJourneyID != nil {
                item["journeyId"] = *sm.ActiveJourneyID
                item["activeJourneyId"] = *sm.ActiveJourneyID
        }
        if sm.TargetLaboratoryID != nil {
                item["laboratoryId"] = *sm.TargetLaboratoryID
        }
        if sm.CurrentHolderID != nil {
                item["currentHolderId"] = *sm.CurrentHolderID
        }
        item["requesterId"] = sm.RequesterID
        if sm.LocationRecordedAt != nil {
                item["locationRecordedAt"] = util.FormatTime(*sm.LocationRecordedAt)
        }
        return item
}

func journeyWorkItem(j *models.Journey) map[string]interface{} {
        item := map[string]interface{}{
                "kind":            "journey",
                "journeyId":       j.ID,
                "status":          j.Status,
                "routeMode":       j.RouteMode,
                "planVersion":     j.PlanVersion,
                "sampleIds":       j.SampleIDs,
                "assignmentCount": len(j.CollectionAssignmentIDs) + len(j.NodeAssignmentIDs) + len(j.LaboratoryAssignmentIDs),
                "history":         []interface{}{},
        }
        if j.EstimatedDeliveryAt != nil {
                item["estimatedDeliveryAt"] = util.FormatTime(*j.EstimatedDeliveryAt)
        } else {
                item["estimatedDeliveryAt"] = util.FormatTime(util.Now())
        }
        return item
}

func assignmentWorkItem(a *models.Assignment) map[string]interface{} {
        item := map[string]interface{}{
                "kind":         "assignment",
                "assignmentId": a.ID,
                "status":       a.Status,
                "history":      []interface{}{},
        }
        if a.SampleID != nil {
                item["sampleId"] = *a.SampleID
        } else {
                item["sampleId"] = ""
        }
        item["journeyId"] = a.JourneyID
        if a.FromLocationID != nil {
                item["fromLocationId"] = *a.FromLocationID
        }
        if a.ToLocationID != nil {
                item["toLocationId"] = *a.ToLocationID
        }
        item["sequence"] = a.Sequence
        if a.OfferExpiresAt != nil {
                item["offerExpiresAt"] = util.FormatTime(*a.OfferExpiresAt)
        }
        if a.NodeID != nil {
                item["nodeId"] = *a.NodeID
        }
        if a.LaboratoryID != nil {
                item["laboratoryId"] = *a.LaboratoryID
        }
        if a.ExpectedSampleTypeID != nil {
                item["expectedSampleTypeId"] = *a.ExpectedSampleTypeID
        }
        return item
}"}

