	for rows.Next() {
		var id string
		_ = rows.Scan(&id)
		a, err := s.GetAssignment(id)
		if err != nil {
			continue
		}
		a.Status = "declined"
		declinedTo := a.OfferedTo
		a.OfferedTo = nil
		a.Active = false
		_ = s.UpdateAssignment(a)
		if declinedTo != nil {
			s.ApplyDeclinePenalty(*declinedTo)
		}
		newA := *a
		newA.ID = util.NewID()
		newA.Status = "offered"
		newA.Active = true
		newA.WorkerID = nil
		exp := util.Now().Add(time.Duration(models.OfferTimeoutSeconds) * time.Second)
		newA.OfferExpiresAt = &exp
		role := "delivery_partner"
		if a.Kind == "collection" {
			role = "collection_professional"
		} else if a.Kind == "node" {
			role = "node_handler"
		} else if a.Kind == "laboratory" {
			role = "laboratory_team"
		}
		var loc *string
		if a.NodeID != nil {
			loc = a.NodeID
		}
		if a.LaboratoryID != nil {
			loc = a.LaboratoryID
		}
		stID := ""
		if a.SampleID != nil {
			if sm, err := s.GetSample(*a.SampleID); err == nil {
				stID = sm.SampleTypeID
			}
		}
		exclude := map[string]bool{}
		if declinedTo != nil {
			exclude[*declinedTo] = true
		}
		w := s.findEligibleWorker(role, stID, loc, exclude)
		if w != nil {
			newA.OfferedTo = &w.ID
		}
		_ = s.insertAssignment(&newA)
	}
}

