{"path":"/workspace/frontend/src/MapView.tsx","command":"create","file_text":"import React, { useEffect, useRef } from 'react'
import maplibregl from 'maplibre-gl'
import { Protocol } from 'pmtiles'

type Marker = {
  id: string
  lat: number
  lon: number
  label?: string
  color?: string
}

export default function MapView({ markers = [] as Marker[], center }: { markers?: Marker[]; center?: [number, number] }) {
  const ref = useRef<HTMLDivElement>(null)
  const mapRef = useRef<maplibregl.Map | null>(null)
  const markersRef = useRef<maplibregl.Marker[]>([])

  useEffect(() => {
    if (!ref.current || mapRef.current) return
    const protocol = new Protocol()
    maplibregl.addProtocol('pmtiles', protocol.tile)

    const map = new maplibregl.Map({
      container: ref.current,
      style: '/map-assets/style.json',
      center: center || [77.5946, 12.9716],
      zoom: 11,
      attributionControl: true,
    })
    map.addControl(new maplibregl.NavigationControl(), 'top-right')
    mapRef.current = map
    return () => {
      markersRef.current.forEach(m => m.remove())
      map.remove()
      mapRef.current = null
      maplibregl.removeProtocol('pmtiles')
    }
  }, [])

  useEffect(() => {
    const map = mapRef.current
    if (!map) return
    markersRef.current.forEach(m => m.remove())
    markersRef.current = markers.map(m => {
      const el = document.createElement('div')
      el.style.width = '14px'
      el.style.height = '14px'
      el.style.borderRadius = '50%'
      el.style.background = m.color || '#1f4b99'
      el.style.border = '2px solid white'
      el.style.boxShadow = '0 0 0 1px rgba(0,0,0,0.25)'
      el.title = m.label || m.id
      const marker = new maplibregl.Marker({ element: el }).setLngLat([m.lon, m.lat]).addTo(map)
      if (m.label) {
        marker.setPopup(new maplibregl.Popup({ offset: 12 }).setText(m.label))
      }
      return marker
    })
  }, [markers])

  return <div className="map-box" role="region" aria-label="Live network map" ref={ref} />
}"}

{"path":"/workspace/frontend/src/App.tsx","command":"create","file_text":"import React, { useEffect, useMemo, useState } from 'react'
import * as api from './api'
import MapView from './MapView'

type Session = {
  userId: string
  username: string
  roles: string[]
  activeRole: string
  fullName?: string
}

const NAV_BY_ROLE: Record<string, { id: string; label: string }[]> = {
  administrator: [
    { id: 'work', label: 'Work queue' },
    { id: 'monitor', label: 'Operations monitor' },
    { id: 'map', label: 'Live map' },
    { id: 'admin', label: 'Administration' },
    { id: 'audit', label: 'Audit trail' },
    { id: 'sample', label: 'Sample lookup' },
  ],
  dispatcher: [
    { id: 'work', label: 'Work queue' },
    { id: 'monitor', label: 'Operations monitor' },
    { id: 'map', label: 'Live map' },
    { id: 'audit', label: 'Audit trail' },
    { id: 'sample', label: 'Sample lookup' },
  ],
  requester: [
    { id: 'work', label: 'My requests' },
    { id: 'request', label: 'New request' },
    { id: 'serviceability', label: 'Serviceability check' },
    { id: 'sample', label: 'Sample status' },
    { id: 'map', label: 'Map' },
  ],
  collection_professional: [
    { id: 'work', label: 'Collection work' },
    { id: 'location', label: 'Record location' },
    { id: 'map', label: 'Map' },
  ],
  delivery_partner: [
    { id: 'work', label: 'Delivery work' },
    { id: 'location', label: 'Record location' },
    { id: 'map', label: 'Map' },
  ],
  node_handler: [
    { id: 'work', label: 'Node work' },
    { id: 'capacity', label: 'Node capacity' },
    { id: 'map', label: 'Map' },
  ],
  laboratory_team: [
    { id: 'work', label: 'Laboratory work' },
    { id: 'capacity', label: 'Laboratory capacity' },
    { id: 'map', label: 'Map' },
  ],
}

export default function App() {
  const [session, setSession] = useState<Session | null>(null)
  const [boot, setBoot] = useState<any>(null)
  const [error, setError] = useState('')
  const [page, setPage] = useState('work')
  const [loading, setLoading] = useState(!!api.getToken())

  useEffect(() => {
    if (!api.getToken()) {
      setLoading(false)
      return
    }
    api.bootstrap()
      .then((data) => {
        setBoot(data)
        setSession({
          userId: data.user.userId,
          username: data.user.username,
          roles: data.user.roles || [],
          activeRole: data.user.activeRole || '',
          fullName: data.user.fullName,
        })
        if (data.user.roleSelectionRequired) setPage('role')
      })
      .catch((e) => {
        api.setToken(null)
        setError(e.message)
      })
      .finally(() => setLoading(false))
  }, [])

  async function handleLogin(username: string, password: string) {
    setError('')
    try {
      const data = await api.login(username, password)
      api.setToken(data.sessionToken)
      const b = await api.bootstrap()
      setBoot(b)
      setSession({
        userId: data.userId,
        username,
        roles: data.roles || [],
        activeRole: data.activeRole || '',
      })
      setPage(data.activeRole ? 'work' : 'role')
    } catch (e: any) {
      setError(e.message || 'Login failed')
      throw e
    }
  }

  async function handleSelectRole(role: string) {
    setError('')
    const data = await api.selectRole(role)
    setSession((s) => s ? { ...s, activeRole: data.activeRole, roles: data.roles } : s)
    const b = await api.bootstrap()
    setBoot(b)
    setPage('work')
  }

  function signOut() {
    api.setToken(null)
    setSession(null)
    setBoot(null)
    setPage('work')
    setError('')
  }

  if (loading) return <div className="login-wrap"><div className="card">Loading…</div></div>
  if (!session) return <LoginView onLogin={handleLogin} error={error} />

  const role = session.activeRole
  const nav = role ? (NAV_BY_ROLE[role] || [{ id: 'work', label: 'Work' }]) : [{ id: 'role', label: 'Select role' }]

  return (
    <div className="app-shell">
      <header className="topbar">
        <h1>Lab Sample Pickup & Delivery</h1>
        <div className="meta">
          <span aria-label="signed-in-user">{session.fullName || session.username}</span>
          <span className="badge" aria-label="active-role">{role ? api.ROLE_LABELS[role] || role : 'No role selected'}</span>
          {session.roles.length > 1 && (
            <label className="row" style={{ gap: 6 }}>
              <span className="muted">Role context</span>
              <select
                aria-label="Role switcher"
                value={role || ''}
                onChange={async (e) => {
                  try { await handleSelectRole(e.target.value) } catch (err: any) { setError(err.message) }
                }}
              >
                {!role && <option value="">Select role…</option>}
                {session.roles.map((r) => (
                  <option key={r} value={r}>{api.ROLE_LABELS[r] || r}</option>
                ))}
              </select>
            </label>
          )}
          <button className="secondary" aria-label="Sign out" onClick={signOut}>Sign out</button>
        </div>
      </header>
      <div className="layout">
        <nav className="nav" aria-label="Main navigation">
          {nav.map((item) => (
            <button key={item.id} className={page === item.id ? 'active' : ''} onClick={() => setPage(item.id)}>
              {item.label}
            </button>
          ))}
        </nav>
        <main className="content">
          {error && <div className="error" role="alert">{error}</div>}
          {!role && page !== 'role' && (
            <div className="card">
              <h2>Select active role</h2>
              <p className="muted">Choose the role you are currently working under. This does not change your assigned roles.</p>
              <RolePicker roles={session.roles} onSelect={handleSelectRole} />
            </div>
          )}
          {page === 'role' && (
            <div className="card">
              <h2>Select active role</h2>
              <RolePicker roles={session.roles} onSelect={handleSelectRole} />
            </div>
          )}
          {role && page === 'work' && <WorkView role={role} onError={setError} />}
          {role && page === 'request' && <RequestView onError={setError} />}
          {role && page === 'serviceability' && <ServiceabilityView onError={setError} />}
          {role && page === 'sample' && <SampleView onError={setError} />}
          {role && page === 'monitor' && <MonitorView boot={boot} onError={setError} />}
          {role && page === 'map' && <MapPage boot={boot} onError={setError} />}
          {role && page === 'audit' && <AuditView onError={setError} />}
          {role && page === 'admin' && <AdminView onError={setError} />}
          {role && page === 'location' && <LocationView onError={setError} />}
          {role && page === 'capacity' && <CapacityView role={role} session={session} onError={setError} />}
        </main>
      </div>
    </div>
  )
}

function LoginView({ onLogin, error }: { onLogin: (u: string, p: string) => Promise<void>; error: string }) {
  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')
  const [localError, setLocalError] = useState('')
  const [busy, setBusy] = useState(false)

  async function submit(e: React.FormEvent) {
    e.preventDefault()
    setLocalError('')
    setBusy(true)
    try {
      await onLogin(username, password)
    } catch (err: any) {
      setLocalError(err.message || 'Invalid credentials')
    } finally {
      setBusy(false)
    }
  }

  return (
    <div className="login-wrap">
      <form className="login-card stack" onSubmit={submit} aria-label="Sign in form">
        <h1>Sign in</h1>
        <p className="muted">Lab sample pickup and delivery network</p>
        {(error || localError) && <div className="error" role="alert">{localError || error}</div>}
        <label>
          <span className="label">Username</span>
          <input aria-label="Username" value={username} onChange={(e) => setUsername(e.target.value)} required autoComplete="username" />
        </label>
        <label>
          <span className="label">Password</span>
          <input aria-label="Password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} required autoComplete="current-password" />
        </label>
        <button type="submit" disabled={busy} aria-label="Sign in">{busy ? 'Signing in…' : 'Sign in'}</button>
      </form>
    </div>
  )
}

function RolePicker({ roles, onSelect }: { roles: string[]; onSelect: (r: string) => Promise<void> }) {
  const [err, setErr] = useState('')
  return (
    <div className="stack">
      {err && <div className="error">{err}</div>}
      <div className="row">
        {roles.map((r) => (
          <button key={r} aria-label={`Select role ${api.ROLE_LABELS[r] || r}`} onClick={async () => {
            try { await onSelect(r) } catch (e: any) { setErr(e.message) }
          }}>
            {api.ROLE_LABELS[r] || r}
          </button>
        ))}
      </div>
    </div>
  )
}

function WorkView({ role, onError }: { role: string; onError: (s: string) => void }) {
  const [work, setWork] = useState<any>({ pending: [], inProgress: [], completed: [] })
  const [msg, setMsg] = useState('')

  async function refresh() {
    try {
      const data = await api.listRoleWork(role)
      setWork(data)
    } catch (e: any) {
      onError(e.message)
    }
  }
  useEffect(() => { refresh() }, [role])

  async function accept(id: string) {
    try {
      await api.acceptAssignment(id)
      setMsg('Assignment accepted')
      refresh()
    } catch (e: any) { onError(e.message) }
  }
  async function decline(id: string) {
    try {
      await api.declineAssignment(id)
      setMsg('Assignment declined')
      refresh()
    } catch (e: any) { onError(e.message) }
  }

  function Section({ title, items, actions }: any) {
    return (
      <div className="card">
        <h2>{title}</h2>
        {(!items || items.length === 0) && <p className="muted">No items</p>}
        <table className="table" aria-label={title}>
          <thead>
            <tr>
              <th>Kind</th><th>ID</th><th>Status</th><th>Details</th><th></th>
            </tr>
          </thead>
          <tbody>
            {(items || []).map((it: any, idx: number) => (
              <tr key={it.assignmentId || it.sampleId || it.journeyId || idx}>
                <td><span className="badge">{it.kind}</span></td>
                <td>{it.assignmentId || it.sampleId || it.journeyId}</td>
                <td>{it.status}</td>
                <td className="muted">
                  {it.locationStale ? <span className="badge warn">Location stale</span> : null}
                  {it.serviceability ? ` ${it.serviceability}` : ''}
                  {it.currentHolderId ? ` holder=${it.currentHolderId.slice(0, 8)}` : ''}
                </td>
                <td className="row">
                  {actions && it.kind === 'assignment' && it.status === 'offered' && (
                    <>
                      <button aria-label={`Accept assignment ${it.assignmentId}`} onClick={() => accept(it.assignmentId)}>Accept</button>
                      <button className="secondary" aria-label={`Decline assignment ${it.assignmentId}`} onClick={() => decline(it.assignmentId)}>Decline</button>
                    </>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    )
  }

  return (
    <div>
      <div className="row" style={{ marginBottom: 12 }}>
        <h2 style={{ margin: 0 }}>Current and past work</h2>
        <button className="secondary" onClick={refresh} aria-label="Refresh work">Refresh</button>
      </div>
      {msg && <div className="success">{msg}</div>}
      <Section title="Pending / offered" items={work.pending} actions />
      <Section title="In progress" items={work.inProgress} />
      <Section title="Completed / past" items={work.completed} />
    </div>
  )
}

function RequestView({ onError }: { onError: (s: string) => void }) {
  const [form, setForm] = useState({
    latitude: '12.97', longitude: '77.59', originType: 'home',
    sampleTypeId: '', deliveryHours: '6', containerType: 'standard',
    temperatureMinC: '2', temperatureMaxC: '25',
  })
  const [types, setTypes] = useState<any[]>([])
  const [result, setResult] = useState<any>(null)
  const [validation, setValidation] = useState('')

  useEffect(() => {
    // bootstrap may not include types; create request needs sampleTypeId from admin setup
    api.readServiceabilitySnapshot().catch(() => null)
  }, [])

  function set(k: string, v: string) { setForm((f) => ({ ...f, [k]: v })) }

  async function submit(e: React.FormEvent) {
    e.preventDefault()
    setValidation('')
    setResult(null)
    const lat = Number(form.latitude), lon = Number(form.longitude)
    if (Number.isNaN(lat) || Number.isNaN(lon)) {
      setValidation('Origin coordinates must be valid numbers')
      return
    }
    if (!form.sampleTypeId) {
      setValidation('Sample type is required')
      return
    }
    const now = new Date()
    const deadline = new Date(now.getTime() + Number(form.deliveryHours) * 3600 * 1000)
    try {
      const data = await api.createCollectionRequest({
        origin: { latitude: lat, longitude: lon },
        originType: form.originType,
        requestedAt: now.toISOString(),
        deliveryDeadline: deadline.toISOString(),
        earliestCollectionAt: now.toISOString(),
        latestCollectionAt: new Date(now.getTime() + 2 * 3600 * 1000).toISOString(),
        sampleTypeId: form.sampleTypeId,
        containerType: form.containerType,
        temperatureMinC: Number(form.temperatureMinC),
        temperatureMaxC: Number(form.temperatureMaxC),
