              <option value="home">Home</option>
              <option value="clinic">Clinic</option>
              <option value="node">Node</option>
            </select>
          </label>
          <label><span className="label">Sample type ID</span><input aria-label="Sample type ID" value={form.sampleTypeId} onChange={(e) => set('sampleTypeId', e.target.value)} required /></label>
          <label><span className="label">Delivery window (hours)</span><input aria-label="Delivery hours" value={form.deliveryHours} onChange={(e) => set('deliveryHours', e.target.value)} /></label>
          <label><span className="label">Container type</span><input aria-label="Container type" value={form.containerType} onChange={(e) => set('containerType', e.target.value)} /></label>
        </div>
        <button type="submit">Create request</button>
