{"path":"/workspace/app-setup/reset.sh","command":"create","file_text":"#!/usr/bin/env bash
set -euo pipefail
cd /workspace

export DATABASE_URL="${DATABASE_URL:-postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable}"
export MONGODB_URI="${MONGODB_URI:-mongodb://127.0.0.1:27017/arena}"

echo "==> Resetting application datastores"

# Build a tiny reset helper if needed
RESET_BIN=/workspace/backend/bin/resetdb
if [ ! -x "$RESET_BIN" ] || [ /workspace/backend/cmd/resetdb/main.go -nt "$RESET_BIN" ] 2>/dev/null; then
