  cat > /workspace/backend/cmd/resetdb/main.go <<'GO'
package main

import (
        "fmt"
        "log"
        "os"

        "labpd/internal/db"
        "labpd/internal/service"
)

func main() {
        d, err := db.Connect()
        if err != nil {
                log.Fatal(err)
        }
