	_, _, ok := h.requireAuth(w, r)
	if !ok {
		return
	}
	afterID := int64(0)
	for _, key := range []string{"since", "after", "afterId"} {
		if v := r.URL.Query().Get(key); v != "" {
			if n, e := toFloat(v); e {
				afterID = int64(n)
			}
		}
	}
	events, err := h.Store.ListRealtimeEvents(afterID, 100)
	if err != nil {
		util.WriteError(w, 500, "internal_error", err.Error())
		return
	}
	cursor := afterID
	for _, ev := range events {
		if id, ok := ev["id"].(int64); ok && id > cursor {
			cursor = id
		}
		// json numbers may decode as float in generic maps when re-encoded; id is int64 from store
		switch t := ev["id"].(type) {
		case int64:
			if t > cursor {
				cursor = t
			}
		case int:
			if int64(t) > cursor {
				cursor = int64(t)
			}
		case float64:
			if int64(t) > cursor {
				cursor = int64(t)
			}
		}
	}
	util.WriteData(w, 200, map[string]interface{}{"events": events, "cursor": cursor})
}"}
